SELECT 'moj-all-verified-judgments-review-002-chunk-132' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3399f0ff-8ff1-5a72-9337-c2f769321c1a","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -إقرار بالدعوى -ادعاء مرض نفسي -تقرير طبي -عدم وجود سوابق -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34166318","case_number":"33670030","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/18","year":"1434","subject":"سرقة -سرقة سيارة -إقرار بالدعوى -ادعاء مرض نفسي -تقرير طبي -عدم وجود سوابق -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                  ‫رقم الصك ‪ 34166318 :‬تاريخه ‪:‬‬\n            ‫‪1434/03/18‬هـ رقم الدعوى ‪33670030:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34209215‬تاريخه‪1434/5/7 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬إقــرار بالدعــوى ‪ -‬ادعــاء مــرض نفســي ‪ -‬تقريــر‬\n      ‫طبــي ‪ -‬عــدم وجــود ســوابق ‪ -‬تعزيــر بالســجن واجللــد والتوصيــة‬\n                                                           ‫باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                  ‫‪-1‬ما قرره الفقهاء من السرقة من غير حرز فيها التعزير‪.‬‬\n                 ‫‪-2‬ما نصت عليه التعليمات من عدم إطالة سجن األجنبي‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــى العــام ضــد مقيــم بطلــب إثبــات إدانتــه بســرقة ســيارة‬\n      ‫مــن أمــام إحــدى املطاعــم وهــي بوضــع التشــغيل وطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n      ‫بــاغ مفــاده تعــرض ســيارته للســرقة وعثــر عليهــا بقيــادة املدعــى عليــه‬\n      ‫واعتــرف بســرقتها ‪ ،‬أقــر املدعــى عليــه بالدعــوى ودفــع أنــه قام بالســرقة‬\n      ‫مــن غيــر إدراك نظــر ًا ألنــه مريــض نفســي ‪ ،‬متــت مخاطبــة مستشــفى‬\n      ‫الصحــة النفســية للتأكــد مــن حالــة املدعــى عليــه ‪ ،‬ورد اجلــواب مــن إن‬\n      ‫املدعــى عليــه يعانــي مــن اضطــراب القلــق ولكــن ذلــك غيــر مؤثــر علــى‬\n      ‫اإلدراك ‪ ،‬مت احلكــم بإدانــة املدعــى عليــه مبــا نســب إليــه و التعزيــر‬\n      ‫بالســجن واجللــد التوصيــة باإلبعــاد عــن البــاد مت تصديــق احلكــم مــن‬\n\n‫‪261‬‬\n\f                                                          ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33670030‬وتاريــخ ‪ 1433/11/22‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332086688‬وتاريــخ ‪ 1433/11/22‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1434/03/18‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.........‬وادعــى بقولــه بصف ــتي مدعيـ ـ ًا عامـ ـ ًا‬\n‫يف دائ ــرة االدع ــاء الع ــام مبدين ــة الري ــاض أدع ــي علــى ‪ 35......... :‬ســنة‬\n‫ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).........‬حيــث أنه بتاريخ‬\n‫‪1433/9/10‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل دوريــات االمــن اثــر‬\n‫بــاغ ملركــز شــرطة ‪ .....‬مــن املواطــن ‪......... /‬يفيــد فيــه بســرقة ســيارته‬\n‫مــن نــوع ‪ .......‬حتمــل لوحــة رقــم (‪ ).........‬مــن امــام احــدى املطاعــم علــى‬\n‫طريــق ‪ ............‬وهــي بوضــع التشــغيل وباســتجوابه اعتــرف بأنــه شــاهد‬\n‫ســيارة متوقفــة بجــوار إحــدى املطاعــم علــى طريــق ‪ ............‬وهــي بوضــع‬\n‫التشــغيل فقــام بســرقتها لغــرض التنقــل عليهــا والهــروب بهــا إلــى حــي‬\n‫‪ ............‬ثــم رجــع الــى حــي ‪ .....‬مــرورا بحــي ‪ .....‬ومت القبــض عليــه وهــو‬\n‫يقــود الســيارة املســروقة وصــادق علــى أقوالــه شــرعا وأســفرت اجــراءات‬\n‫التحقيــق الــى توجيــه االتهــام للمدعــى عليــه بســرقة ســيارة مــن نــوع ‪......‬‬\n‫حتمــل لوحــة رقــم (‪ ).........‬مــن امــام احــد املطاعــم بشــارع ‪ ............‬وهــي‬\n                           ‫بوضــع التشــغيل وذلــك لألدلــة والقرائــن التاليــة ‪- :‬‬\n‫‪ -1‬اعترافــه املصــدق شــرعا بســرقة الســيارة واملــدون علــى صفحــة رقــم‬\n\n                                                                                         ‫‪262‬‬\n\f                                                    ‫(‪ )14‬مــن ملــف التحقيــق رقــم (‪.)1‬‬\n                                ‫‪ -2‬ماتضمنه محضر القبض املرفق لفه رقم (‪.)6‬‬\n                       ‫وبالبحث عن سوابقه لم يعثر له على سوابق حتى تاريخه‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪ -‬هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه بــأن مــا ذكــره املدعــي‬\n      ‫العــام صحيــح جملــة وتفصيــا حيــث قمــت بســرقة الســيارة املذكــورة‬\n      ‫وهــي يف وضــع التشــغيل ألنــي مصــاب بحالــة نفســية وقــد حصــل ذلــك‬\n      ‫وأنــا غيــر مــدرك ملــا حصــل هكــذا أجــاب عليــه فقــد جــرى الكتابــة‬\n      ‫ملجمــع األمــل للصحــة النفســية للكشــف علــى املذكــور واإلفــادة عــن‬\n      ‫حالتــه النفســية مبوجــب خطابنــا رقــم ‪ 3431821‬يف ‪1434/1/6‬ه ـ‬\n      ‫فوردنا تقريرهم رقم ‪ 44/22/1652/371‬يف ‪1434/2/26‬هـ املتضمن‬\n      ‫أنــه مت الكشــف علــى املذكــور وتبــن أنــه يعانــي مــن اضطــراب القلــق‬\n      ‫وليــس ملرضــه تأثيــر علــى إدراكــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وملصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام وألن ســرقة‬\n      ‫الســيارة يف وضــع التشــغيل تعــد ســرقة مــن غيــر حــرز وقــد قــرر الفقهــاء‬\n      ‫أن الســرقة مــن غيــر حــرز فيــه التعزيــر ونظــرا إلــى أن حالتــه النفســية ال‬\n      ‫تؤثــر علــى إدراكــه ونظــرا لعــدم وجــود ســوابق مســجلة عليــه ولكــون‬\n      ‫احلالــة النفســية تقضــي بالتخفيــف عنــه وقــد نصــت التعليمــات علــى عــدم‬\n      ‫إطالــة مــدة ســجن األجنبــي ألن مصيــره الترحيــل لذلــك كلــه فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه بســرقة ســيارة مــن نــوع ‪ .......‬حتمــل لوحــة رقــم‬\n      ‫(‪ ).........‬مــن امــام احــد املطاعــم بشــارع ‪ ............‬وهــي بوضــع التشــغيل‬\n\n\n‫‪263‬‬\n\f‫وحكمــت بتعزيــره بســجنه ملــدة عشــرة أشــهر اعتبــارا مــن تاريــخ إيقافــه‬\n‫وجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات مقــدار كل‬\n‫دفعــة أربعــون جلــدة بــن كل دفعــة واألخــرى مــدة ال تقــل عــن أســبوعني‬\n‫وأوصيــت بترحيلــه إلــى بلــده بعــد انتهــاء محكوميتــه وبعــرض ذلــك علــى‬\n‫الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب متييــز احلكــم بــدون‬\n‫الئحــة وقــرر املدعــى عليــه القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34/522824‬وتاريــخ‪/8‬‬\n‫‪ 1434/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة‬\n‫الشيخ‪........./‬املسجل برقم ‪ 34166318‬وتاريخ ‪1434/ 3 /18‬هـ اخلاص‬\n‫بدعــوى املدعــي العــام ضــد‪ ( ......... /‬ســوداني اجلنســية ) التهامــه بقضيــة‬\n‫ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قــررت الدائــرة باألكثريــة املصادقــة علــى احلكــم و اهلل املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪264‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":261,"source_page_end":264,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e148f637519c23e594d8b2498e30dd57ccf82c559df0c951576dcad9f110d8f","normalized_text_hash":"c6da69571d3b623254909122144bb7af089abe648424e7c5d113d45abbe3af9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p261-34166318"},{"id":"8efb0345-0116-59e3-80a4-e92b5caf079d","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -نشل -تشكيل عصابة -تنوع املضبوطات -التعزير للمدعى عليهما الثالث والرابع بالسجن واجللد لوجود سوابق قضائية -رد دعوى املدعى العام للمدعى عليه األول والثاني .","document_number":"3441904","case_number":"33671081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"سرقة -نشل -تشكيل عصابة -تنوع املضبوطات -التعزير للمدعى عليهما الثالث والرابع بالسجن واجللد لوجود سوابق قضائية -رد دعوى املدعى العام للمدعى عليه األول والثاني .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3441904 :‬تاريخه ‪1434/02/19:‬هـ‬\n                         ‫رقم القضية ‪33671081 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34232554‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬نشــل ‪ -‬تشــكيل عصابــة ‪ -‬تنــوع املضبوطــات ‪ -‬التعزيــر للمدعــى‬\n      ‫عليهمــا الثالــث والرابــع بالســجن واجللــد لوجــود ســوابق قضائيــة ‪ -‬رد‬\n                           ‫دعــوى املدعــى العــام للمدعــى عليــه األول والثانــي ‪.‬‬\n\n\n\n\n                                                     ‫قاعدة ( األصل براءة الذمة ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام علــى أربعــة أشــخاص بتكويــن عصابــة يف النشــل‪،‬‬\n      ‫حيــث مت القبــض علــى املدعــى عليهــم مــن قبــل اجلهــات األمنيــة حيــث‬\n      ‫توفــرت معلومــات عنهــم بتكويــن عصابــة يف النشــل ‪ ،‬وأنهــم مــن أربــاب‬\n      ‫الســوابق ‪ ،‬ويقومــون بالنشــل مــن املعتمريــن يف األماكــن املزدحمــة ‪،‬‬\n      ‫وكانــت حتركاتهــم مريبــة ‪ ،‬فتــم القبــض عليهــم ‪ ،‬ووجــد مــع املدعــى‬\n      ‫عليهــم مبالــغ ماليــة مختلفــة ‪ ،‬وعمــات متنوعــة ‪ ،‬وأجهــزة جوال ‪ ،‬طلب‬\n      ‫تعزيرهــم لقــاء ذلــك وتشــديد العقوبــة علــى املدعــى عليــه الثالــث لكثــرة‬\n      ‫ســوابقه ‪ ،‬واحلكــم بإيــداع مــا مت ضبطــه معهــم يف بيــت املــال ‪ ،‬أنكــر‬\n      ‫املدعــى عليهــم مــا جــاء بدعــوى املدعــى العــام ‪ُ ،‬ط ِلــب مــن املدعــى العــام‬\n      ‫بينتــه علــى دعــواه فقــرر أنــه ليــس لديــه اإل مــا جــاء يف أوراق املعاملــة ‪,‬‬\n      ‫وباالطــاع عليهــا لــم يجــد القاضــي الدليــل القاطــع الدانتهــم ‪ ،‬صــدر‬\n\n‫‪265‬‬\n\f‫احلكــم بــرد دعــوى املدعــى العــام ضــد األول والثانــي ‪ ،‬وتعزيــر املدعــى‬\n‫عليهــم الثالــث والرابــع نظــر ًا لوجــود ســوابق عليهــم يف النشــل ‪ ،‬قنــع‬\n‫املدعــى عليهــم وقــرر املدعــى العــام اعتراضــه علــى احلكــم بالئحــة ‪،‬‬\n                               ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33671081‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332090688‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/19‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي العــام املعمــد مــن‬\n‫مرجعــه باخلطــاب رقــم ه ـ م ‪/2 /‬ا‪ 340/‬وتاريــخ ‪1434/1/24‬ه ـ ودعــى‬\n‫علــى احلاضريــن معــه كال مــن ‪ ، ...../1‬البالــغ مــن العمــر (‪ )50‬عام ـ ًا‬\n‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة عــن جــوازات‬\n‫الريــاض برقــم‪ ).....(.....‬و‪ ...../2‬البالــغ مــن العمــر (‪ )54‬عام ـ ًا أفغانــي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة الصــادرة مــن مركــز شــرطة‬\n‫املنصــور برقــم(‪ ).....‬يف ‪1433/9/17‬ه ـ و‪ ، ...../3‬البالــغ مــن العمــر‬\n‫(‪ )54‬عامـ ًا ‪ ،‬أفغانــي اجلنســية ـ مبوجــب البطاقــة البديلــة الصــادرة مــن‬\n‫مركــز شــرطة املنصــور برقــم(‪ ).....‬يف ‪1433/9/17‬ه ـ و‪ ، ...../4‬البالــغ‬\n‫مــن العمــر (‪ )52‬عام ـ ًا ‪ ،‬أفغانــي اجلنســية ـ مبوجــب البطاقــة البديلــة‬\n‫الصــادرة مــن مركــز شــرطة املنصــور برقــم(‪ )......‬يف ‪1433/9/17‬ه ـ‬\n‫قائــا يف دعــواه حيــث انــه بتاريــخ ‪1433/9/17‬ه ـ قبــض علــى املدعــى‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫عليهــم مــن قبــل شــعبة التحريــات والبحــث اجلنائــي بشــرطة العاصمــة‬\n      ‫املقدســة لتوفــر معلومــات عنهــم بتكويــن عصابــة يف النشــل وأنهــم‬\n      ‫مــن إربــاب الســوابق ويتزعمهم(الثانــي) ويقومــون مبمارســة النشــل مــن‬\n      ‫املعتمريــن مــن داخــل احلــرم امللكــي الشــريف واملناطــق املجــاورة لــه‬\n      ‫املزدحمــة باملعتمريــن وتكــون حتركاتهــم أثنــاء محاولــة النشــل علــى‬\n      ‫شــكل مجموعــات لغــرض التغطيــة وامليدانيــة أثنــاء ممارســة عمليــات‬\n      ‫النشــل ومبراقبتهــم أتضــح أنهــم يســكنون يف شــقق (‪ ).....‬بالغرفــة رقــم‬\n      ‫(‪ ).....‬وكانــت حتركاتهــم مريبــة وحذريــن يف حتركاتهــم ويقومــون‬\n      ‫بالتغلغــل بــن املعتمريــن باألماكــن املزدحمــة هــذا وبعــد التأكــد مــن‬\n      ‫تواجــد جميــع أفــراد العصابــة بداخــل ســكنهم مت إعــداد اخلطــة الالزمــة‬\n      ‫يف متــام الســاعة الســابعة صباح ـ ًا املوافــق تاريخــه أعــاه جــرى دخــول‬\n      ‫ســكنهم الكائــن بشــقق ‪ ......‬وبتفتيشــهم عثــر مــع (الثانــي) علــى ألفــن‬\n      ‫وخمســة وثمانــن (‪)2085‬ريــا ًال ســعودي ًا ‪ ،‬ومــع (الثالــث) أربعــة أالف‬\n      ‫ومائتــن وخمســة وعشــرين (‪)4225‬ريــا ًال ســعودي ًا وجهــاز هاتــف نقــال‬\n      ‫نــوع ‪ ...‬وجــواز ســفر باســمه ‪ ،‬ومــع (الرابــع) وجــد بحوزتــه جهــاز مــن نــوع‬\n                                                ‫‪ ...‬بنــي اللــون وجــواز ســفر باســمه ‪.‬‬\n      ‫وبتفتيــش الغرفــة التابعــة للمذكوريــن وجــد حتــت الفرشــة التــي كانــوا‬\n      ‫يجلســون بهــا علــى مبلــغ ألــف وأربعمائــة(‪)1400‬دوالر أمريكــي وألفــن‬\n      ‫وتســعمائة وخمســة وثالثــن (‪ )2935‬ريــا ًال ســعودي ًا وجهــاز ‪ ...‬فضــي‬\n      ‫اللــون وقــد ذكــر جميــع مــن يف الغرفــة عــدم عالقتــه بالنقــود وجهــاز‬\n      ‫الهاتــف النقــال املضبوطــة بالغرفــة (فتــم حجــز جميــع املضبوطــات‬\n                                 ‫بصنــدوق آألمانــات مبركــز شــرطة املنصــور) ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه (األول) أقــر بأنــه ضبــط بحوزتــه جهــاز هاتف‬\n\n\n‫‪267‬‬\n\f‫نقــال واحــد فقــط عائــد إليــه وأمــام مــا يتعلــق بالــدوالرات األمريكيــة‬\n‫ذكــر أنــه شــاهد (الثانــي) يضعهــا أســفل الفرشــة قبــل دخــول رجــال‬\n‫البحــث اجلنائــي عليهــم بوقــت قصيــر ‪ .‬وباســتجواب املدعــى عليــه‬\n‫(الثانــي) أقــر بأنــه ضبــط بحوزتــه مبلــغ قــدرة ثالثــة أالف وثالثمائــة‬\n‫(‪ )3300‬ريــال ســعودي وأن جهــاز الهاتــف النقــال مــن نــوع ‪ ...‬أســود اللــون‬\n‫عائــد إليــه والــذي مت العثــور عليــه حتــت الفرشــة بداخــل الشــقة ‪ ،‬وأنه لم‬\n‫يضــع املبلــغ املالــي املضبــوط حتــت الفرشــة ‪.‬وباســتجواب املدعــى عليــه‬\n‫(الثالــث) أقــر أنــه ضبــط بحوزتــه خمســة أالف (‪ )5000‬ريــال ســعودي‬\n‫وألــف(‪ )1000‬دوالر أمريكــي الــذي وجــد أســفل الفرشــة وجهــاز جــوال‬\n‫أحضرهــا معــه مــن أفغانســتان ‪ .‬وباســتجوابه املدعــى عليــه (الرابــع) أقــر‬\n‫أنــه ضبــط بحوزتــه ألفــا (‪)2000‬ريــال ســعودي و(‪)1900‬ألــف وتســعمائة‬\n‫دوالر أمريكــي وجهــاز هاتــف نقــال وجــدت حتــت الفرشــة وقــد انتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام لهــم بتكويــن عصابــة نشــل وذلــك لألدلــة‬\n                                                             ‫والقرائــن التاليــة‪-:‬‬\n‫‪-1‬مــا ورد مبحضــر القبــض والتفتيــش املنــوه عنه املرفــق على اللفتني(‪)3‬‬\n                                                                             ‫و(‪, )4‬‬\n‫‪-2‬تناقــض أقوالهــم حيــال النقــود وجهــاز الهاتــف النقــال املضبوطــة‬\n‫حتــت الفرشــة بغرفتهــم كمــا يتضــح مــن أقوالهــم املنــوه عنهــا املدونــة‬\n        ‫علــى الصفحــات(‪ )13-2‬بامللفــن املرفقــن علــى اللفــه (‪. )2-1‬‬\n‫‪-3‬تنــوع املضبوطــات واختــاف العمــات دون تقــدمي املدعــى عليهــم‬\n                                                           ‫ملبــرر علــى جمعهــا ‪.‬‬\n‫وبالبحث عن ســوابقهم عثر (للثالث) على خمس(‪ )5‬ســوابق نشــل عودة‬\n‫بعــد إبعــاده باســم‪ .....‬وعثــر (للرابــع) علــى ســابقتني (األولــى‪ :‬لعــب القمار‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫وامليســر والثانيــة‪ :‬نشــل) ولــم يعثــر (لــأول والثانــي) علــى ســوابق مســجلة‬\n      ‫بحقهمــا‪ .‬وحيــث أن مــا قــام بــه املدعــى عليهــم فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n      ‫تعزيريــة والتشــديد علــى (الثالــث) لقــاء تعــدد ســوابقه اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي نائــب وزيــر الداخليــة رقــم(‪)93958/5/5/1‬‬\n      ‫وتاريــخ ‪1429/8/23‬ه ـ واحلكــم وبإيــداع املضبوطــات بيــت املــال‬\n      ‫اســتناد ًا للمــادة(‪ )92‬مــن نظــام اإلجــراءات اجلزائيــة ‪( .‬علمـ ًا بــأن اليوجــد‬\n      ‫بالقضيــة حــق خــاص) وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــم‬\n      ‫وهــم يتحدثــون العربيــة أنكروهــا كل علــى حــدة جملــة وتفصيــا وقال‬\n      ‫األول والثانــي ال ســوابق لدينــا وقــرر الثالــث قائــا لــدي خمســة ســوابق‬\n      ‫نشــل اخــذت محكوميتهــا وقــرر الرابــع قائــا لــدي ســابقتني نشــل‬\n      ‫وقمــار اخــذت محكوميتهــا جميعــا لــدي وبعــرض ذلــك علــى املدعــي‬\n      ‫العــام قــال الصحيــح ماذكرتــه يف دعــواي وبينتــي ماذكــرت وبالرجــوع‬\n      ‫الــى ادلــة املدعــي العــام وجــدت دليلــه األول محضــر القبــض لفــة‬\n      ‫رقــم ‪ 4/3‬وبالرجــوع اليــه وجتــه يتضمــن (أنــه بتاريــخ ‪1433/9/17‬ه ـ‬\n      ‫قبــض علــى املدعــى عليهــم مــن قبــل شــعبة التحريــات والبحــث اجلنائــي‬\n      ‫بشــرطة العاصمــة املقدســة لتوفــر معلومــات عنهــم بتكويــن عصابــة‬\n      ‫يف النشــل وأنهــم مــن إربــاب الســوابق ويتزعمهم(الثانــي) ويقومــون‬\n      ‫مبمارســة النشــل مــن املعتمريــن مــن داخــل احلــرم امللكــي الشــريف‬\n      ‫واملناطــق املجــاورة لــه املزدحمــة باملعتمريــن وتكــون حتركاتهــم أثنــاء‬\n      ‫محاولــة النشــل علــى شــكل مجموعــات لغــرض التغطيــة وامليدانيــة‬\n      ‫أثنــاء ممارســة عمليــات النشــل ومبراقبتهــم اتضــح أنهــم يســكنون يف‬\n      ‫شــقق ‪ .........‬بالغرفــة رقــم( ) وكانــت حتركاتهــم مريبــة وحذريــن يف‬\n\n\n‫‪269‬‬\n\f‫حتركاتهــم ويقومــون بالتغلغــل بــن املعتمريــن باألماكــن املزدحمــة‬\n‫هــذا وبعــد التأكــد مــن تواجــد جميــع أفــراد العصابــة بداخــل ســكنهم‬\n‫مت إعــداد اخلطــة الالزمــة يف متــام الســاعة الســابعة صباح ـ ًا املوافــق‬\n‫تاريخــه أعــاه جــرى دخــول ســكنهم الكائــن بشــقق منــار التقــوي(‪)1‬‬\n‫وبتفتيشــهم عثــر مــع (الثانــي) علــى ألفــن وخمســة وثمانــن (‪)2085‬‬\n‫ريــا ًال ســعودي ًا ‪ ،‬ومــع (الثالــث) أربعــة أالف ومائتــن وخمســة وعشــرين‬\n‫(‪)4225‬ريــا ًال ســعودي ًا وجهــاز هاتــف نقــال نــوع ‪ ...‬وجــواز ســفر باســمه‬\n‫‪ ،‬ومــع (الرابــع) وجــد بحوزتــه جهــاز مــن نــوع ‪ ...‬بنــي اللــون وجــواز ســفر‬\n‫باســمه‪ .‬وبتفتيــش الغرفــة التابعــة للمذكوريــن وجــد حتــت الفرشــة التــي‬\n‫كانــوا يجلســون بهــا علــى مبلــغ ألــف وأربعمائــة(‪)1400‬دوالر أمريكــي‬\n‫وألفــن وتســعمائة وخمســة وثالثــن (‪ )2935‬ريــا ًال ســعودي ًا وجهــاز ‪...‬‬\n‫فضــي اللــون وقــد ذكــر جميــع مــن يف الغرفــة عــدم عالقتــه بالنقــود‬\n‫وجهــاز الهاتــف النقــال املضبوطــة بالغرفــة (فتم حجــز جميع املضبوطات‬\n‫بصنــدوق آألمانــات مبركــز شــرطة املنصــور) ‪ .‬وبعرضــه علــى املدعــى‬\n‫عليهــم اقــروا بالقبــض وانكــروا الباقــي كمــا رجعــت لدليــل املدعــى‬\n‫عليــه الثانــي وهــو تناقــض اقــوال املدعــى عليهــم حيــال النقــود والهاتــف‬\n‫املضبــوط حتــت الفرشــة بغرفتهــم املــدون ص ‪ 13-2‬لفــة ‪2-1‬وبالرجــوع‬\n‫الــى اســتجوابتهم وجدتهــا كالتالــي (باســتجواب املدعــى عليــه (األول)‬\n‫أقــر بأنــه ضبــط بحوزتــه جهــاز هاتــف نقــال واحــد فقط عائد إليــه وأمام‬\n‫مــا يتعلــق بالــدوالرات األمريكيــة ذكــر أنــه شــاهد (الثانــي) يضعهــا‬\n‫أســفل الفرشــة قبــل دخــول رجــال البحــث اجلنائــي عليهــم بوقــت قصيــر‪.‬‬\n‫وباســتجواب املدعــى عليــه (الثانــي) أقــر بأنــه ضبــط بحوزتــه مبلــغ قــدرة‬\n‫ثالثــة أالف وثالثمائــة (‪ )3300‬ريــال ســعودي وأن جهــاز الهاتــف النقــال‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫مــن نــوع ‪...‬أســود اللــون عائــد إليــه والــذي مت العثــور عليــه حتــت الفرشــة‬\n         ‫بداخــل الشــقة ‪ ،‬وأنــه لــم يضــع املبلــغ املالــي املضبــوط متــت الفرشــة ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه (الثالــث) أقــر أنــه ضبــط بحوزتــه خمســة‬\n      ‫أالف (‪ )5000‬ريــال ســعودي وألــف(‪ )1000‬دوالر أمريكــي الــذي‬\n      ‫وجــد اســفل الفرشــة وجهــاز جــوال أحضرهــا معــه مــن أفغانســتان‪.‬‬\n      ‫وباســتجوابه املدعــى عليــه (الرابــع) أقــر أنــه ضبط بحوزتــه ألفا (‪)2000‬‬\n      ‫ريــال ســعودي و(‪)1900‬ألــف وتســعمائة دوالر أمريكــي الــذي وجهــاز‬\n      ‫هاتــف نقــال وجــدت حتــت الفرشــة ) وبعرضهــا علــى املدعــى عليهــم‬\n      ‫قالــوا ارتبكنــا مــن اخلــوف واعتــرف الرابــع حمايــة اهلل بــان التســعمائة‬\n      ‫دوالر عائــدة لــه وقــرر الثالــث بــأن االلــف دوالر لــه واكتفــى املدعــي‬\n      ‫العــام مباذكــر فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــة وبنــاء علــى‬\n      ‫انــكار املدعــى عليهــم للدعــوى وعــدم قيــام الدليــل القاطــع علــى ادانتهم‬\n      ‫بهــا وألن ماذكــر املدعــي العــام مــن ادلــة توجــه االتهــام للمدعــى عليــه‬\n      ‫الثالــث والرابــع لوجــود ســوابق عليهمــا يف النشــل والترقــى إلدانتهــم‬\n      ‫واألصــل بــراءة الذمــة واعتبــارا لعــدم وجــود ســوابق علــي املدعــى عليهمــا‬\n      ‫األول والثانــي ‪ .....‬و‪ .......‬وألن أقوالهــم بعــد االطــاع عليهــا حتقيقــا لــم‬\n      ‫اجــد فيهــا تناقضــا ظاهــرا بــل وافقــت أقوالهــم قضــاء لــذا كلــه فقــد‬\n      ‫حكمــت مبايلــي‪:‬أوال‪ :‬لــم ثثبــت لــدي ادانــة املدعــى عليهــم مبانســب اليــه‬\n                                      ‫ورددت دعــوى املدعــي العــام املتعلقــة بذلــك‬\n      ‫ثانيــا‪ :‬تتوجــه التهمــة نحــو املدعــى عليهمــا الثالــث والرابــع و وحكمــت‬\n      ‫بتعزيرهمــا لقــاء ذلــك بســجن الثالــث ثمانيــة أشــهر مــن تاريــخ ايقافــه‬\n      ‫وســجن الرابــع ســتة أشــهر مــن تاريــخ ايقافــه وبعرضــه عليهــم قنعــوا بــه‬\n      ‫وقــرر املدعــي العــام االعتــراض بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n‫‪271‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/19‬هـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 3441904‬وتاريــخ‬\n‫‪1434/2/19‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ .....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.....‬‬\n‫املدعــى عليــه باكســتاني اجلنســية ورفقــاه ‪ ،‬املتهمــن يف قضيــة نشــل‪،‬‬\n‫احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":265,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a30d4ccef7a4196c6b41e04b873b1bad334cf2178feb09930e0f9f1597a5ee3","normalized_text_hash":"e81abed8079651cbbdd32bee5a274e22c91947c1b1c3eddc167c976c412de2a2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p265-3441904"},{"id":"41c29c5e-c8b6-5dcb-9c36-3462df34a755","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة بعض محتويات سيارة -مشاركة يف السرقة -رجوع عن اإلقرار -درء حد السرقة -التعزير بالسجن واجللد .","document_number":"3426043","case_number":"33672049","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"سرقة -سرقة بعض محتويات سيارة -مشاركة يف السرقة -رجوع عن اإلقرار -درء حد السرقة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3426043 :‬تاريخه ‪1434/01/28 :‬‬\n                       ‫هـ رقم الدعوى ‪33672049 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34186406‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة بعــض محتويــات ســيارة ‪ -‬مشــاركة يف الســرقة ‪ -‬رجــوع‬\n                 ‫عــن اإلقــرار ‪ -‬درء حــد الســرقة ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                     ‫‪ -‬قوله صلى اهلل عليه وسلم ( احلدود تدرأ بالشبهات ) ‪.‬‬\n      ‫‪ -‬قــال ابــن أبــي عمــر ـ ـ رحمــه اهلل ـ ـ مــن احلنابلــة يف الشــرح الكبيــر‬\n      ‫(‪ ( )208-207/26‬إن شــرط إقامــة احلــد باإلقــرار ‪ -‬البقــاء عليــه إلــى‬\n                              ‫متــام احلــد ‪ -‬فــإن رجــع عــن إقــراره كــف عنــه )‬\n          ‫‪ -‬قال صاحب اإلنصاف عقبه ‪ ( -:‬هذا املذهب يف جميع احلدود ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه باتهامــه بتكســير زجــاج‬\n      ‫ســيارات‪ ،‬وســرقة أربــع مســجالت فيهــا وكاميــرا تلفزيونيــة‪ ،‬تقــدم‬\n      ‫بعــض األشــخاص لإلبــاغ عــن تعــرض زجــاج ســياراتهم للكســر‬\n      ‫وســرقة بعــض احملتويــات منهــا وال يتهمــوا أحــد ًا بالســرقة‪ ،‬وبعــد‬\n      ‫البحــث والتحــري توصلــت اجلهــات األمنيــة أن اللذيــن يقومــان بتكســير‬\n      ‫الســيارات ‪ ،‬همــا كال مــن املدعــى عليــه ‪ ،‬وشــخص آخــر ( فــرزت لــه‬\n      ‫أوراق مستقلة ) ‪ ،‬ومت القبض عليه ‪ ،‬واتضح أنه من أرباب السوابق ‪،‬‬\n      ‫وأقــر بالتهمــة املنســوبة إليــه ‪ ،‬وصــدق اعترافــه شــرعاً‪ ،‬و طلــب املدعــي‬\n‫‪273‬‬\n\f‫العــام إقامــة حــد الســرقة بحقــه كونــه ســرق مــن حــرز محتــرم بالغــا‬\n‫نصابـاً‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام ‪ .‬ـ ـ طلــب مــن‬\n‫املدعــي العــام بينتــه علــى دعــواه ‪ ،‬فذكــر إقــرار املدعــى عليــه املصــدق‬\n‫شــرع ًا و بســؤال املدعــى عليــه عنــه ‪ :‬أعتــرف بصحتــه ‪ ،‬و دفــع بــأن ذلــك‬\n‫كان بإكــراه مــن احملقــق ‪ ،‬و بســؤاله البينــة علــى اإلكــراه ‪ ،‬قرر عدم‬\n‫وجــود بينــة لديــه‪ ،‬ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة و فيهــا‬\n‫احملاضــر املصدقــة مــن البحــث اجلنائــي‪ ،‬حكمــت احملكمــة بصــرف‬\n‫النظــر عــن طلــب املدعــي العــام بإقامــة حــد الســرقة علــى املدعــى عليــه‪،‬‬\n‫واحلكــم بتعزيــر املدعــى عليــه بالســجن و اجللــد نظــر ًا لتوجــه التهمــة‬\n‫القويــة بحقــه‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬و املدعــي العــام لــم يقنــع‬\n‫باحلكــم و طلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة‪ ،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬باالشــتراك مــع صاحــب الفضيلــة‬\n‫الشــيخ ‪ ....‬وصاحــب الفضيلــة الشــيخ ‪ ....‬القضــاة يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ ....‬وتاريــخ ‪ ...‬املقيــدة باحملكمــة برقــم ‪ ....‬وتاريــخ‬\n‫‪ ....‬ففــي يــوم اإلثنــن املوافــق‪ ...‬افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا‬\n‫قــدم املدعــي العــام ‪ ....‬الئحــة دعــواه ضــد ‪ ....‬ســعودي مبوجــب الســجل‬\n‫ا إنــه بتاريــخ ‪ ....‬تقــدم املواطــن ‪ ، ...‬بشــكوى إلــى‬ ‫املدنــي رقــم ‪ ....‬قائ ـ ً‬\n‫شــرطة ‪ ......‬مفيــد ًا عــن تعــرض زجــاج ســيارته مــن نــوع ‪ .....‬للتكســير‬\n‫وســرق منهــا ام بــي ثــري وكاميــرا مراقبــة تلفزيونيــة ‪،‬وذلــك أثنــاء‬\n\n                                                                                         ‫‪274‬‬\n\f      ‫وقوفهــا أمــام ســكنه بحــي ‪ ....‬وال يتهــم أحــد ًا بعينــه وبتاريــخ ‪ ...‬تقــدم‬\n      ‫املواطــن‪ .../‬بشــكوى لقســم شــرطة ‪ .......‬مفيــد ًا عــن تعــرض زجــاج‬\n      ‫ســيارته مــن نــوع ‪ .....‬للكســر ومحاولــة ســرقة املســجل وال يتهــم أحــد ًا‬\n      ‫وبتاريــخ ‪ ...‬تقــدم املواطــن ‪ ..../‬بشــكوى لقســم الشــرطة مفيــد ًا عــن‬\n      ‫تعــرض زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحــد ًا وبتاريــخ‬\n      ‫‪ ....‬تقــدم املواطــن ‪ .../‬بشــكوى لقســم الشــرطة مفيــد ًا عــن تعــرض‬\n      ‫زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحـ ًـد بذلــك وبــذات‬\n      ‫التاريــخ تقــدم املقيــم‪( ... /‬باكســتاني اجلنسية)لقســم الشــرطة مفيــد ًا‬\n      ‫عــن تعــرض زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحـ ًـد‬\n      ‫بذلــك وبتاريــخ ‪ ....‬تقــدم املواطــن ‪ ...‬لقســم الشــرطة مفيــد ًا عــن تعــرض‬\n      ‫زجــاج ســيارته للكســر وســرقة مســجل الســيارة وال يتهــم أحـ ًـد بذلــك‬\n      ‫وبتاريــخ ‪ ....‬توصلــت أجهــزة البحــث والتحــري بشــرطة ‪ ......‬إلــى أن‬\n      ‫ال مــن املدعــى‬  ‫اللذيــن يقومــان بتكســير زجــاج الســيارات همــا ك ً‬\n      ‫عليــه‪، .....‬واآلخــر ‪( ....‬مت فــرز أوراق مســتقلة لــه مــن قبــل شــرطة‬\n      ‫محافظــة ‪ ......‬وســيتم رفعهــا لســعادة محافــظ ‪ .....‬الحق ـاً) ومت القبــض‬\n      ‫علــى املدعــى عليــه بتاريــخ ‪ ...‬وبالبحــث عــن ســوابقه اتضح أنــه مت ايداعه‬\n      ‫دار املالحظــة االجتماعيــة بتهمــة قيامــه بكســر مرايــا ســيارتني‬\n      ‫وســرقتهما وقــد حكــم عليــه بااللتحــاق بحلقــة حتفيــظ قــرآن ملــدة ســتة‬\n      ‫أشــهر وإذا لــم يلتــزم يســجن شــهر وقــد مت تقديــر تلفيــات ســيارة املواطــن‬\n      ‫‪ ....‬مبلــغ وقــدره (‪2000‬ريــال)‪ .‬وتلفيــات ســيارة املواطــن‪ ... /‬فتقــدر مببلــغ‬\n      ‫(‪ )510‬أمــا ســيارة املواطــن‪ ... /‬فتــم تقديــر تلفيــات ســيارته مببلــغ وقــدره‬\n      ‫(‪410‬ريــال) أمــا تلفيــات ســيارة املقيــم‪ ... /‬فتقــدر مبلــغ وقــدره‬\n      ‫(‪1430‬ريال)وقــد مت االتصــال علــى املواطــن ‪ ...‬إلحظــار تقديــر تلفيــات‬\n\n\n‫‪275‬‬\n\f‫ســيارته ولكنــه لــم يحضــر حتــى تاريخــه ‪،‬أمــا مايخــص تقديــر تلفيــات‬\n‫املواطــن ‪ ...‬فقــد تنــازل عــن حقــه اخلــاص وباســتجواب املدعــى عليــه أقــر‬\n‫أنــه قبــل يومــن مــن تاريــخ القبــض عليــه كان بشــارع ‪ ...‬مبحافظــة ‪......‬‬\n‫وحضــر لــه شــخص يدعــى ‪ ....‬وطلــب منــه مســجل ســيارة ثــم ركــب معــه‬\n‫واجتهــا إلــى حــي ‪ ......‬بحث ـ ًا عــن ســيارة فلــم يجــدا ثــم خرجــا مــن احلــي‬\n‫وشــاهدا ســيارة مــن نــوع ‪ .....‬فتوقفــا عندهــا وقــام ‪ ...‬بأخــذ ســكروب‬\n‫وكســر الزجــاج اخللفــي للســيارة مــن جهــة اليمــن ثــم قــام بفــك املســجل‬\n‫وأعطــاه للمدعــو ‪ ...‬مقابــل (‪150‬ريال)‪،‬وأقــر كذلــك أنــه ســبق وأن قــام‬\n‫بكســر زجــاج ســيارة مــن نــوع ‪ ......‬كانــت متوقفــة بالقــرب مــن مركــز‬\n‫‪ .....‬محــاوال الســرقة منهــا لكنــه لــم يجــد شــيئ ًا ولــم يكــن معــه أحــد ًا ‪،‬‬\n‫كمــا أقــر بكســر الزجــاج اخللفــي مــن جهــة اليســار لســيارة مــن نــوع ‪.....‬‬\n‫وقــام بســرقة املســجل وبيعــه علــى أحــد األشــخاص مببلــغ (‪150‬ريــال)‬\n‫ولــم يشــاركه أحــد ‪ ،‬كمــا أقــر بكســر زجــاج ســيارة مــن نــوع ‪ .....‬ولــم‬\n‫يجــد فيهــا شــيئ ًا ‪ ،‬وأقــر كذلــك بأنــه قــام بكســر زجــاج ســيارة مــن‬\n‫نــوع ‪ ......‬وســرق منهــا مشــغل صوتيــات(‪ )MP3‬ولــم يشــاركه أحــد ًا وال‬\n‫يــزال اجلهــاز يف املنــزل ‪ ،‬كمــا أقــر بكســر زجــاج ســيارة مــن نــوع ‪.....‬‬\n‫بهــدف الســرقة لكنــه لــم يجــد فيهــا شــيئ ًا ‪ ،‬وبانتقــال املختصــن يف‬\n‫جهــة الضبــط ومعاينــة الســيارات التــي مت ذكرهــا بالشــكوى تبــن‬\n‫لهــم تعــرض تلــك الســيارات لكســر زجاجهــا والســرقة منهــا وبضبــط‬\n‫شــهادة املواطــن ‪ ..../‬أفــاد بــأن قــام بشــراء مســجل ســيارة مــن املدعــى‬\n‫عليــه مببلــغ (‪150‬ريــال) وال يعلــم بأنــه مســروق وقــد انتهــى التحقيــق مــع‬\n‫املدعــى عليــه ‪ ....‬إلــى اتهامــه بتكســير زجــاج (‪ )6‬ســت ســيارات وســرقة‬\n‫أربــع مســجالت منهــا وجهــاز صوتيــات (‪،)MP3‬وكاميــرا تلفزيونيــة‬\n\n\n                                                                                         ‫‪276‬‬\n\f      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 -:‬مــا جــاء يف إقــراره املصــدق شــرع ًا‬\n      ‫املــدون علــى الصفحــة رقــم (‪)6‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ -2 .)3‬ماجــاء يف إفــادة املواطــن ‪ .....‬املــدون علــى الصفحــة رقــم (‪)14‬‬\n      ‫مــن ملــف االســتدالل املرفــق لفــه رقــم (‪ -3)1‬مــا جاء يف محضــر االنتقال‬\n      ‫واملعاينــة املــدون علــى الصفحــة رقــم (‪)4‬مــن ملــف االســتدالل املرفــق لفــه‬\n      ‫رقــم (‪ ،)2‬و محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)10‬‬\n      ‫مــن ملــف االســتدالل املرفــق لفــه رقــم (‪ ،)7‬ومحضــر االنتقــال واملعاينــة‬\n      ‫املــدون علــى الصفحــة رقــم (‪)2‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ ،)8‬ومحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)2‬مــن‬\n      ‫ملــف االســتدالل املرفــق لفــه رقــم (‪ ،)6‬ومحضــر االنتقــال واملعاينــة‬\n      ‫املــدون علــى الصفحــة رقــم (‪)2‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ ،)5‬ومحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)2‬مــن‬\n      ‫ملــف االســتدالل املرفــق لفــه رقــم (‪-4)4‬ماجــاء باحملضــر املعــد مــن قبــل‬\n      ‫التحريــات والبحــث اجلنائــي املرفــق لفــه رقــم (‪-5.)41‬ماجــاء يف تقديــر‬\n      ‫التلفيــات املرفــق لفــه رقــم (‪)61-60-59-58-57-56-55-54‬وحيــث‬\n      ‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم مــن حــرزه‬\n      ‫بعــد هتكــه يزيــد عــن النصــاب الشــبهة لــه فيــه ولكــون اجلانــي مكلف‬\n      ‫وغيــر مكــره أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة (علمــا‬\n      ‫بــأن احلــق اخلــاص اليــزال قائم ـ ًا فيمــا يخــص املدعــي ‪ ...‬واملدعــي ‪...‬‬\n      ‫واملدعــي ‪ ، ...‬وانتهــى بالتنــازل فيمــا يخــص املدعــي ‪ ...‬واملقيــم ‪)...‬‬\n      ‫ا‬ ‫وبســؤال املدعــى عليــه عمــا جــاء يف الئحــة املدعــي العــام أجــاب قائ ـ ً‬\n\n\n‫‪277‬‬\n\f‫كل مــا جــاء يف الئحــة املدعــي العــام غيــر صحيــح فلــم أقــم بتكســير‬\n‫زجــاج ســت ســيارات وســرقة أربــع مســجالت منهــا وجهــاز صوتيــات‬\n‫(‪ )MP3‬وكاميــرا تلفزيونيــة وال شــيئ ًا مــن ذلــك هكــذا أجــاب فجــرى‬\n‫ا بينتــي مــايف أوراق املعاملــة‬ ‫ســؤال املدعــي العــام عــن بينتــه فأجــاب قائـ ً‬\n‫فجــرى االطــاع علــى أوراق املعاملــة ومنهــا اإلقــرار املصــدق شــرع ًا‬\n‫واملــدون علــى لفــة (‪ )3‬صفحــة (‪ )6‬وهــذا نــص احلاجــة منــه ( أقــر أنــا‬\n‫احلــدث ‪ ...‬أننــي قمــت بتكســير زجــاج عــدة ســيارات وذلــك مبحافظــة‬\n‫‪ ......‬وهــي ‪ .......‬رقــم اللوحــة‪ ... ...‬كانــت متوقفــة بحــارة األحــوال املدنيــة‬\n‫وذلــك قبــل ثــاث أيــام حيــث قمــت بكســر زجاجهــا اخللفــي األميــن‬\n‫بواســطة طابوقــة وقمــت بفــك املســجل بواســطة ســكروب وقمــت ببيعــه‬\n‫علــى املدعــو ‪ ...‬مببلــغ (‪ )150‬ريــال أيض ـ ًا وقمــت بكســر زجاجــة ‪......‬‬\n‫حيــث كانــت متوقفــة بشــارع عشــرين حيــث قمــت بكســر زجاجهــا‬\n‫األمامــي األيســر وقمــت بتفتيشــها ولــم أحصــل شــيء وقمــت بكســر‬\n‫زجــاج ســيارة مــن نــوع ‪ .......‬حيــث قمــت بكســر الزجــاج اخللفــي األيســر‬\n‫ولــم أعثــر علــى شــيء بداخلهــا وقمــت بكســر زجــاج ســيارة مــن نــوع ‪......‬‬\n‫حيــث قمــت بكســر زجاجهــا األميــن ولــم أعثــر علــى شــيء بداخلهــا‬\n‫وقمــت بكســر زجــاج ‪ ......‬حيــث قمــت بكســر زجاجهــا األميــن وذلــك‬\n‫قبــل خمســة عشــر يومـ ًا ولــم أعثــر علــى شــيء هــذا إقــراري وعليــه جــرى‬\n‫ا صحيــح أننــي‬     ‫التوقيــع) فجــرت مجابهتــه بهــذا اإلقــرار فأجــاب قائ ـ ً‬\n‫قلــت ذلــك ولكــن احملقــق قــال لــي اعتــرف وأخرجــك اآلن وأكرهنــي‬\n‫علــى هــذا اإلقــرار فســألناه هــل لديــك بينــة فأجــاب قائــا ليــس لــدي‬\n‫بينــة كمــا جــرى االطــاع علــى إفــادة املواطــن ‪ ...‬لفــة(‪ )1‬صفحــة (‪)14‬‬\n‫وهــذا نــص احلاجــة منهــا ( أقــر أنــا املواطــن ‪ ....‬بأننــي اشــتريت مــن املدعــو‬\n\n\n                                                                                          ‫‪278‬‬\n\f      ‫‪ ....‬قبــل شــهر تقريب ـ ًا مســجل تويوتــا مببلــغ قــدره ألــف وخمســمئة ريــال‬\n      ‫حيــث وجدتــه بشــارع عشــرين علــى قدميــه وكان لوحــده وعرضــه علــي‬\n      ‫واشــتريته منــه وال أعلــم هــل هــو مســروق أو ال) فجــرى ســؤال املدعــى‬\n      ‫ا هــذا الــكالم غيــر صحيــح كمــا جــرى‬           ‫عليــه عــن ذلــك فأجــاب قائ ـ ً‬\n      ‫االطــاع علــى محاضــر االتصــال واملعاينــة لفــه (‪ 2‬ـ ‪ 4‬ـ ‪ 5‬ـ ‪ 6‬ـ ‪ 7‬ـ ‪ )8‬كمــا‬\n      ‫جــرى االطــاع علــى احملضــر املعــد مــن قبــل التحريــات والبحــث اجلنائــي‬\n      ‫لفــة (‪ )41‬واملتضمــن ( أفيدكــم أنــا آمــر دوريــات البحــث اجلنائــي وبعــد‬\n      ‫التحــري عــن األشــخاص الذيــن يقومــون بكســر زجــاج الســيارات‬\n      ‫وســرقة املســجالت وتفتيشــها وســرقة مــا بهــا مــن محتويــات وبعــد‬\n      ‫التحــري والبحــث الدقيــق عــن األشــخاص اتضــح لــي ووردتنــا معلومــات‬\n      ‫ال مــن املدعــو ‪...‬‬\n                        ‫مــن مصــادري اخلاصــة أن الذيــن يقومــون بالســرقة ك ً‬\n      ‫واملدعــو‪ ....‬هــذا للعلــم واإلحاطــة ) وبســؤال املدعــى عليــه عــن جميــع‬\n      ‫ا ‪ :‬ال صحــة لذلــك والصحيــح مــا ذكــرت ثــم ســألنا‬            ‫ذلــك أجــاب قائ ـ ً‬\n      ‫ا ال ســوابق علــي وهلل احلمــد ثــم‬‫املدعــى عليــه عــن ســوابقه فأجــاب قائـ ً‬\n      ‫جــرى ســؤال األطــراف هــل لديهــم مــا يضيفــون فأجــاب كل واحــد‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫منهمــا بأنــه ال إضافــة لديــه فبنـ ً‬\n      ‫وبعــد االطــاع علــى طيــات املعاملــة وإلنــكار املدعــى عليــه مانســب إليــه‬\n      ‫ا وبالنظــر إلــى إقــرار املدعــى عليــه املصــدق شــرع ًا‬         ‫جملــة وتفصي ـ ً‬\n      ‫واملذكــور أعــاه وإلــى إفــادة املواطــن ‪ ....‬وكذلــك إلــى محاضــر‬\n      ‫االنتقــال واملعاينــة ومحضــر التحريــات والبحــث اجلنائــي املذكــور أعــاه‬\n      ‫ولرجــوع املدعــى عليــه عــن إقــراره وادعائــه اإلكــراه ولكــون الرجــوع‬\n      ‫عــن اإلقــرار مقبــول قــال صاحــب الشــرح ( إن شــرط إقامــة احلــد باإلقرار‬\n      ‫البقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) ‪207/26‬‬\n\n\n‫‪279‬‬\n\f‫ـ ‪ 208‬قــال صاحــب اإلنصــاف ( هــذا املذهــب يف جميــع احلــدود ) وألن‬\n‫ادعــاء اإلكــراه شــبهة يــدرأ بهــا احلــد وقــد روي عــن النبــي صلــى اهلل‬\n‫عليــه وســلم أنــه قــال ( احلــدود تــدرأ بالشــبهات ) وبعــد تأكــد مــن خلــو‬\n‫صحيفــة املدعــى عليــه مــن الســوابق كمــا هــو مــدون يف طيــات املعاملــة‬\n‫وحلداثــة ســنه وجلميــع مــا تقــدم فلــم يثبــت لدينــا إدانــة ‪ ....‬بتكســير زجــاج‬\n‫(‪ )6‬ســت ســيارات وســرقة أربــع مســجالت منهــا وجهــاز صوتيــات‬\n‫(‪ )MP3‬وكاميــرا تلفزيونيــة وقررنــا صــرف النظــر عــن طلــب املدعــي‬\n‫العــام إقامــة حــد الســرقة علــى املدعــى عليــه ولكــن لتوجــه التهمــة‬\n‫القويــة عليــه فقــد قررنــا تعزيــره مبــا يلــي‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ملــدة‬\n‫ســنتني ونصــف مــع احتســاب املــدة التــي أمضاهــا يف التوقيــف ثاني ـاً‪:‬‬\n‫جلــد املدعــى عليــه مائتــان وخمســون جلــدة مفرقــة علــى خمــس دفعــات‬\n‫بــن كل دفعــة والتــي تليهــا مــاال يقــل عــن عشــرة أيــام وبذلــك حكمنــا‬\n‫وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة باحلكــم وقــرر املدعــي‬\n‫العــام املعارضــة مــع تقــدمي الئحــة وأفهــم مبقتضــى تعليمــات االســتئناف‬\n‫وأن عليــه تقــدمي الئحــة اعتراضيــة خــال مــدة أقصاهــا ثالثــون يومـ ًا مــن‬\n‫تاريــخ اســتالمه نســخة مــن احلكــم وإذا لــم يقــدم الئحتــه خــال هــذه‬\n‫املــدة فســترفع املعاملــة إلــى محكمــة االســتئناف كاملتبــع وقــد جــرى‬\n‫تســليم املدعــي العــام نســخة مــن احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n    ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/01/26‬هـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم ‪ ...‬وتاريــخ‬\n‫‪1434/3/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n\n\n                                                                                            ‫‪280‬‬\n\f      ‫القضــاة الشــيخ ‪ ...‬والشــيخ ‪ ...‬و‪ ....‬برقــم ‪ ....‬وتاريــخ ‪1434/1/28‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ....‬يف قضيــة ســرقة وقــد تضمــن‬\n      ‫القــرار حكــم أصحــاب الفضيلــة علــى النحــو املفصــل فيــه وبدارســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر باالكثريــة املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم‪.‬‬\n\n\n\n\n‫‪281‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":273,"source_page_end":281,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f3a288ae60c71c2e61311c9444fa182d65f1e1f6f351d130b0fed0da05ba067","normalized_text_hash":"ba9362846027bba31b990262765fc996bd1ea7c7af4c62cf546a06287026a9e4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p273-3426043"},{"id":"bd69d2d5-4ae3-5e80-b0f9-454c16883941","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -قيادة سيارة مسروقة -وجود سوابق قضائية - طلب تشديد عقوبة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن","document_number":"33475432","case_number":"33672219","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/1","year":"1434","subject":"سرقة -سرقة سيارة -قيادة سيارة مسروقة -وجود سوابق قضائية - طلب تشديد عقوبة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33475432 :‬تاريخه‪1433/12/1 :‬هـ‬\n                     ‫رقم الدعوى‪33672219:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 348557‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬قيادة ســيارة مســروقة ‪ -‬وجود ســوابق قضائية ‪-‬‬\n‫طلــب تشــديد عقوبــة ‪ -‬إقــرار بالدعــوى ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n                                                                     ‫واجللد‪.‬‬\n\n\n\n\n                                   ‫القاعدة الفقهية (املرء مؤاخذ بإقراره)‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى املقدمــة مــن املدعــي العــام ضــد شــخص مــن أربــاب‬\n‫الســوابق بســرقة ســيارة متوقفــة أمــام منــزل صاحبهــا وســرقتها‪ ،‬طلــب‬\n‫املدعــي العــام إثبــات مــا ُأســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫وتشــديد العقوبــة لتعــدد ســوابقه‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n‫بــاغ مــن أحــد املواطنــن مفــاده تعــرض ســيارته للســرقة فتــم القبــض‬\n‫علــى املدعــى عليــه وهــو يقــود الســيارة ‪ ،‬أقــر املدعــى عليــه بالدعــوى‬\n‫ومصادقتــه علــى الســوابق‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد‪ ،‬تشــديد التعزيــر بحقــه‪ ،‬مت تصديــق احلكــم مــن‬\n                                                     ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n                                                                                  ‫‪282‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 33672219‬وتاريــخ ‪1433/11/23‬ه ـ‬           ‫ّ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332087425‬وتاريــخ ‪ 1433/11/22‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .......‬و ادعــى علــى احلاضــر معــه ‪ .....‬ســعودي‬\n      ‫اجلنســية ســجل املدنــي رقــم (‪ )........‬أنــه يف متــام الســاعة التاســعة وخمــس‬\n      ‫وثالثــن دقيقــة مســاء يــوم االربعــاء املوافــق ‪1433/10/4‬ه ـ تبلــغ مركــز‬\n      ‫شــرطة املنتــزه مــن املواطــن ‪ ........‬عــن تعــرض ســيارته من نــوع‪ ........‬لوحة‬\n      ‫رقــم (‪ ) .....‬للســرقة مــن أمــام منزلــه وال يتهــم احــد بســرقتها ومت اتخــاذ‬\n      ‫جملــة مــن اإلجــراءات البحثيــة والتعميــم عــن الســيارة املســروقة وبتاريــخ‬\n      ‫‪1433/10/9‬ه ـ أبلــغ املواطــن ‪.......‬عــن تلقيــه اتصــال مــن الشــرطة أنــه‬\n      ‫مت القبــض علــى ســيارته بقيــادة املدعــى عليــه ومت مكاتبــة مديــر‬\n      ‫الشــرطة لبعــث املركبــة والقائــد إلــى مركــز شــرطة ‪ ....‬ومت اســتالم‬\n      ‫املذكــور واملركبــة مــن شــرطة ‪ .....‬وبســماع أقــوال املدعــى عليــه أقــر‬\n      ‫أنــه قــام بأخــذ الســيارة نــوع‪ ......‬مــن أمــام أحــد املنــازل بحــي ‪ ......‬وال‬\n      ‫يعــرف صاحبهــا وأنــه مت القبــض عليــه مــن قبــل شــرطة ‪ ....‬والســيارة‬\n      ‫بقيادتــه وبالبحــث يف ســجله اجلنائــي عثــر لــه علــى ســبع ســوابق وهــي‪:‬‬\n      ‫‪)1‬قيــادة الســيارة وهــو بحالــة ســكر ‪ +‬شــرب املســكر ‪ +‬حيــازة ســاح‬\n      ‫دون ترخيــص ‪ +‬حيــازة الذخيــرة ‪ +‬مخالفــة التعليمــات ‪ ) 2‬ســرقة ســيارة‬\n      ‫‪)3‬ســرقة ســيارة ‪ ) 4‬التلفــظ بألفــاظ غيــر الئقــة ‪ ) 5‬مضاربــة ‪ ) 6‬شــرب‬\n\n‫‪283‬‬\n\f‫مســكرات وســرقة ســيارة ‪ ) 7‬حريــق وقــد أســفر التحقيــق معــه عــن‬\n‫اتهامــه بســرقة الســيارة مــن نــوع ‪ ......‬لوحــة رقــم (‪ )...........‬عندمــا كانت‬\n‫متوقفــة أمــام منــزل صاحبهــا بحــي ‪ ......‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬مــا جــاء باعترافــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪،14، 13‬‬\n‫‪ )15‬املرفــق باللفــة رقــم ( ‪ - 2 .)3‬القبــض عليــه مــن قبــل شــرطة ‪....‬‬\n‫وبقيادتــه الســيارة املســروقة املشــار لــه واملــدون علــى الصفحــة رقــم (‪)20‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره وتشــديد العقوبــة‬\n‫عليــه لتعــدد ســوابقه التــي لــم تردعــه عقوباتهــا الســابقة علم ـ ًا أن احلــق‬\n‫اخلــاص انتهــى بالتنــازل وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح جمل ـ ًة‬        ‫أجــاب قائ ـ ً‬\n‫ا وقــد قمــت بســرقه ســيارة نــوع ‪ .....‬مــن أحــد املنــازل بحــي ‪......‬‬ ‫وتفصيـ ً‬\n‫وجدتهــا مفتحــه االبــواب وذهبــت بهــا إلــى مكــة وتهــت يف الطريــق ومت‬\n‫القبــض علــي يف ‪......‬هكــذا أجــاب وبعــد االطــاع علــى أوراق املعاملــة‬\n‫وجــدت للمدعــى عليــه ســبع ســوابق منهــا ثــاث ســوابق ســرقه وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال الســوابق صحيحــه فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى و اإلجابــة ومبــا أن املدعــى عليــه أقــر مبــا جــاء يف دعــوى‬\n‫املدعــي العــام ومبــا ان املــرء مؤاخــذ بإقــراره ومبــا أن فعلــه هــذا فعــل‬\n‫محــرم ملــا فيــه مــن إيــذاء لألخريــن و اعتــداء علــى أموالهــم وترويعهــم‬\n‫ومبــا أن املدعــى عليــه ســوابق لــم تردعــه عقوباتهــا عــن فعلتــه هــذه لــذا‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بســرقة ســيارة مــن نــوع ‪ ......‬عندمــا‬\n‫كانــت متوقفــة أمــام منــزل صاحبهــا بحــي ‪ ،......‬حكمــت عليــه تعزيــر ًا‬\n\n\n                                                                                        ‫‪284‬‬\n\f                                                                                ‫مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬ســجن املدعــى عليــه ملــدة ســنتني ويحســب لــه كل ســجن بــه يف‬\n      ‫هــذه القضيــة ثانيـاً‪ :‬جلــد املدعــى عليــه ثالثمائــة جلــده مفرقــة علــى ســت‬\n      ‫دفعــات بــن كل دفعــة وأخــرى خمســة عشــر يومـ ًا وبعــرض احلكــم على‬\n      ‫املدعــى عليــه و املدعــي العــام قــررا كل منهمــا عــدم القناعــة وطلبــا‬\n      ‫رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــه و اهلل املوفــق‬\n                ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/12/21‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n      ‫املختصــة بتدقيــق القضايــا اجلزائية مبحكمة االســتئناف مبنطقة حائل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبنطقــة‬\n      ‫حائــل برقــم ‪ 332087425‬يف تاريــخ ‪1434 / 1 / 6 :‬ه ـ واملقيــدة لدينــا‬\n      ‫برقم ‪ 3455854‬يف تاريخ ‪1434 / 1 / 7 :‬هـ املرفق بها القرار الشرعي‬\n      ‫الصــادر مــن صاحــب الفضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة اجلزائية‬\n      ‫مبنطقــة حائــل برقــم ‪ 33475432‬يف تاريــخ‪1433/12/21 :‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد‪ ........ :‬ســعودي بالســجل املدنــي رقــم‪)........( :‬‬\n      ‫بشــأن ســرقه ســيارة وقــد تضمــن القــرار حكــم صاحــب الفضيلــة وفقــه‬\n      ‫اهلل علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار املرفــق ‪ ،‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى ماحكــم‬\n      ‫بــه فضيلتــه بالقــرار املشــار إليــه مــع تنبيــه فضيلتــه ينبغــي وضع شــاهدين‬\n      ‫علــى بصمــه املدعــى عليــه مســتقبال حســب التعليمــات املرعيــة واهلل‬\n                      ‫املوفــق وصلــى وســلم علــى نبينــا محمــد والــه وصحبــه وســلم‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":282,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"87129049b897cf597185605856269565b0e16e07d42461b6181d572928a6d71d","normalized_text_hash":"49cfc3f89645a6c232e236fcdb85a747a9bb61c98c51a655fb2b94cd82065b7a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p282-33475432"},{"id":"072e2627-ed96-5f32-94fd-f363f7f031b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة وتشليحها -اشتراك يف سرقة -تصرف يف مسروق -تستر -تشديد عقوبة -رجوع عن إقرار -طلب بينة على انتزاع اكراه -ثبوت إدانة -رد دعوى لعدم وجود بينة موصلة - تعزير بالسجن واجللد .","document_number":"33476071","case_number":"33675694","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"سرقة -سرقة سيارة وتشليحها -اشتراك يف سرقة -تصرف يف مسروق -تستر -تشديد عقوبة -رجوع عن إقرار -طلب بينة على انتزاع اكراه -ثبوت إدانة -رد دعوى لعدم وجود بينة موصلة - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33476071 :‬تاريخه‪1433/12/22 :‬هـ‬\n                       ‫رقم الدعوى‪33675694:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34983‬تاريخه‪1434/1/7 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة وتشــليحها ‪ -‬اشــتراك يف ســرقة ‪ -‬تصــرف يف‬\n‫مســروق ‪ -‬تســتر ‪ -‬تشــديد عقوبــة ‪ -‬رجــوع عــن إقــرار ‪ -‬طلــب بينــة علــى‬\n‫انتــزاع اكــراه ‪ -‬ثبــوت إدانــة ‪ -‬رد دعــوى لعــدم وجــود بينــة موصلــة ‪-‬‬\n                                                  ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                ‫‪ -‬حديث البينة على املدعي واليمني على املدعى عليه‪.‬‬\n                ‫‪ -‬املال من الضرورات اخلمس التي ورد الشرع بحفظها‪.‬‬\n\n\n\n\n‫دعــوى املدعــى العــام ضــد أربعــة أشــخاص بطلــب إثبــات إدانــة األول‬\n‫بســرقة ســيارة والتصــرف بهــا بتشــليحها واشــتراك الثانــي والثالــث‬\n‫يف تشــليح الســيارة وتســترهما مــع الرابــع علــى األول‪ ،‬وطلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليهــم واحلكــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى‬\n‫املدعــى عليهــم بعــد بالغــن بســرقة ســيارتني وبعــد البحــث والتحــري‬\n‫قبــض علــى املدعــى عليهــم ومت التحقيــق معهــم وباســتجوابهم اعترفــوا‬\n‫مبــا نســب إليهــم ‪ ،‬أقــر املدعــى عليــه األول بالدعــوى ‪ ،‬كما أقر املدعى‬\n‫عليــه الثانــي ‪ ،‬أنكــر املدعــى عليــه الثالــث ‪ ،‬وجــد إقــرار حتقيقــا علــى‬\n‫املدعــى عليــه الثالــث‪ ،‬أنكــر املدعــى عليــه الرابــع ‪ ،‬وعــدم وجــود بينــة‬\n                                                                                     ‫‪286‬‬\n\f      ‫علــى املدعــى عليــه الرابــع ‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليهــم‬\n      ‫األول والثانــي والثالــث بالســجن واجللــد ‪ ،‬ورد دعــوى املدعــى العــام ضــد‬\n         ‫املدعــى عليــه الرابــع‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1433/12/21‬ه ـ لــدي أنــا ‪......‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف افتتحــت اجللســة يف‬\n      ‫الســاعة التاســعة صباحـ ًا بنــاء ًا علــى املعاملــة احملالــة لنــا مــن رئيــس هــذه‬\n      ‫احملكمــة برقــم ‪ 33675694‬يف ‪1433/11/24‬ه ـ واملقيــدة لــدى‬\n      ‫احملكمــة بالقيــد رقــم ‪ 332113017‬يف ‪1433/11/24‬ه ـ ويف هــذه‬\n      ‫ا بصفتــي مدعيـ ًا عامــا يف‬    ‫اجللســة حضــر املدعــي العــام ‪ .......‬وقــرر قائـ ً‬\n      ‫دائــرة التحقيــق واالدعــاء العام مبحافظة القطيــف أدعي على‪،.......-1 :‬‬\n      ‫البالــغ مــن العمــر (‪)21‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬غيــر محصــن ‪ ،‬متســبب ‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1433/10/1‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف اســتنادا للقــرار‬\n      ‫الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ ، ......-2‬البالــغ مــن العمــر‬\n      ‫(‪)21‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر‬\n      ‫محصــن ‪ ،‬متســبب ‪ ،‬املقبــوض عليــه بتاريــخ ‪1433/10/1‬ه ـ ‪ ،‬وأحيــل‬\n      ‫لســجن محافظــة القطيــف اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬هـ ‪ ، .......-3‬البالغ من العمر (‪)23‬عام ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر محصــن ‪ ،‬عاطــل ‪ ،‬املقبــوض‬\n      ‫عليــه بتاريــخ ‪1433/10/1‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف‬\n      ‫اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪،......-4‬‬\n‫‪287‬‬\n\f‫البالــغ مــن العمــر (‪)32‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )......‬محصــن ‪ ،‬موظــف أهلــي ‪ ،‬املقبــوض عليــه بتاريــخ‬\n‫‪1433/10/1‬ه ـ ‪ ،‬مفــرج عنــه اســتناد ًا للمــادة (‪ )120‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم مبحافظــة ‪ ....‬حيــث أنــه بتاريــخ‬\n‫‪1433/9/24‬ه ـ ورد بــاغ ملركــز شــرطة ‪ .....‬مــن قبــل‪ ...... /‬عــن تعــرض‬\n‫ســيارته مــن نــوع ‪ ....‬رقــم اللوحــة (‪ ).....‬للســرقة مــن املوقــع الــذي تركهــا‬\n‫بــه ‪ ....‬علــى شــارع ‪ ....‬بجــوار البنــك ‪ ............‬وبتاريــخ ‪1433/10/1‬ه ـ ورد‬\n‫بــاغ ملركــز شــرطة ‪ ....‬مــن قبــل‪ ..... /‬مخبــر ًا عــن وجــود ســيارة مــن نــوع‬\n‫‪ ....‬مشــلحة مبزرعتــه الواقعــة ‪ .....‬وبانتقــال محقــق القضيــة إلــى موقــع‬\n‫الســيارة املذكــورة اتضــح أن عبــارة عــن مزرعــة بالقــرب مــن كوبــري‬\n‫املطــار وبالوصــول إليــه شــوهدت الســيارة املذكــورة مشــلحة بالكامــل‬\n‫وليــس بهــا كفــرات وباســتجواب املدعــى عليــه األول (‪ )....‬أقــر بقيامــه‬\n‫بســرقة وتشــليح وإخفــاء ســيارة املبلــغ ‪ .....‬مــن نــوع ‪ ......‬وأخبــر بذلــك‬\n‫الثانــي والثالــث وكان الثانــي هــو من يقوم بإيصاله إلى ‪ ....‬وباســتجواب‬\n‫املدعــى عليــه الثانــي (‪ )......‬أقــر بأنــه كان يعلــم بالســرقة وكان يعــاون‬\n‫املدعــى عليــه األول يف تشــليح الســيارة املذكــورة وباســتجواب املدعــى‬\n‫عليــه الثالــث (‪ )....‬أقــر بعلمــه بســرقة املدعــى عليــه األول للســيارة ويعلــم‬\n‫أن أنــه يقــوم بتفكيــك الســيارة املذكــورة وباســتجواب املدعــى عليــه‬\n‫الرابــع (‪ ).....‬أقــر بعلمــه بوجــود الســيارة املســروقة مــن قبــل األول أمــام‬\n‫منزلهــم وقــد انتهــى التحقيــق معهــم إلــى توجيــه االتهــام إليهــم بســرقة‬\n‫األول ســيارة مــن نــوع (‪ ).......‬والتصــرف بهــا بتشــليحها وباشــتراك الثاني‬\n‫والثالــث لــه يف تشــليح الســيارة وتســترهما مــع الرابــع علــى األول وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬إقــرار املدعــى عليــه األول املــدون علــى‬\n\n\n                                                                                        ‫‪288‬‬\n\f      ‫الصفحــة رقــم (‪ )10‬مــن اللفــة رقــم (‪ -2 )1‬إقــرار املدعــى عليــه الثانــي‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )11‬مــن لفــة رقــم (‪ -3 )1‬إقــرار املدعــى‬\n      ‫عليــه الثالــث املــدون علــى الصفحــة رقــم (‪ )12‬مــن لفــة رقــم (‪)1‬‬\n      ‫‪-4‬محضــر االنتقــال واملعاينــة املعــد مــن قبــل فرقــة البحــث اجلنائــي‬\n      ‫بشــرطة مركــز ‪ ......‬رقــم (بــدون) تاريــخ ‪1433/10/1‬ه ـ املنــوه عنــه‬\n      ‫علــى الصفحــة رقــم (‪ )2‬لفــة (‪ -5 )2‬مــا جــاء يف أقــوال املدعــى عليــه‬\n      ‫الرابــع املدونــة علــى الصفحــات رقــم (‪ )12،11،10‬مــن ملــف التحقيــق‬\n      ‫لفــة رقــم (‪ )2‬وبالبحــث عــن ســوابقهم لــم يعثــر لهــم علــى ســوابق جنائيــة‬\n      ‫علــى املســتوى العــام وحيــث إن مــا أقــدم عليــه املذكــورون ‪ -‬وهــم‬\n      ‫بكامــل أهليتهــم املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n      ‫تعزيريــة تزجرهــم وتــردع غيرهــم (علم ـ ًا بــأن احلــق اخلــاص قــد انتهــى‬\n      ‫بالتنــازل) هــذه دعــواي وبــاهلل التوفيــق هــذا كمــا حضــر يف اجللســة ‪.....‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ .....‬وبســؤاله عــن دعــوى املدعــي‬\n      ‫العــام أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬\n      ‫فقــد قمــت بســرقة ســيارة ‪ ......‬مــن نــوع ‪ .....‬مــن بيــت صاحبــه بعــد نزولــه‬\n      ‫منهــا وتصرفــت بهــا بتشــليحها لوحــدي وكان ســبب ذلــك أنني اشــتريت‬\n      ‫مــن املدعــو ‪ .....‬ســيارة أخــرى غيــر هــذه الســيارة واســتلمتها منــه ثــم‬\n      ‫أخذهــا منــي بالغفلــة مــن عنــد بيتــي فغضبــت مــن تصرفــه فقمــت بســرقة‬\n      ‫ســيارته هــذا جوابــي هــذا وقــد حضــر يف اجللســة ‪ ....‬ســعودي مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .........‬وبســؤاله عــن دعــوى املدعــي العــام أجــاب‬\n      ‫بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن أننــي اشــتركت مــع‬\n      ‫املدعــى عليــه األول يف ســرقة الســيارة ‪ .....‬غيــر صحيــح بــل الصحيــح هــو‬\n\n\n‫‪289‬‬\n\f‫أننــي أقــوم بتوصيــل املدعــى عليــه األول ‪ ....‬للســيارة املذكــورة ‪ .....‬حيــث‬\n‫أنــه ال يوجــد لديــه ســيارة وقمــت بتوصيلــه مرتــن وقــد علمــت بــأن‬\n‫الســيارة مســروقة قبــل القبــض علينــا بيومــن ولــم أخبــر عــن ذلــك ألننــي‬\n‫مشــغول وقبــض علينــا عنــد الســيارة املســروقة عنــد بيــت ‪ .....‬هــذا جوابي‬\n‫هــذا كمــا حضــر يف اجللســة ‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n‫‪ ......‬وبســؤاله عــن دعــوى املدعــي العــام أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام يف دعــواه غيــر صحيــح بــل الصحيــح هــو أن املدعــى عليــه ‪ .....‬يقــوم‬\n‫بإصــاح ســيارات عنــد منزلنــا ‪ .....‬وأخبــرت إخوانــي بــأن يكلمــوه‬\n‫وكان مــن ضمــن الســيارات هــذه الســيارة املســروقة إال أننــي لــم أكــن‬\n‫أعلــم أنهــا مســروقة إال بعــد حضــور األدلــة اجلنائيــة هــذا جوابــي هــذا‬\n‫كمــا حضــر يف اجللســة ‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫وبســؤاله عــن دعــوى املدعــي العــام أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n‫يف دعــواه مــن أننــي متســتر علــى املدعــى عليــه األول غيــر صحيــح بــل‬\n‫الصحيــح هــو أننــي كنــت جالــس يف الديوانيــة وســمعتهم يقولــون‬\n‫الســيارة التــي عنــد املنــزل تعــود للمدعــى عليــه ‪ .....‬ولــم أكــن أعلــم أنهــا‬\n‫مســروقة ولــم أشــاهدها ولــم أشــاهد املدعــى عليــه يقــوم بتشــليحها هــذا‬\n‫جوابــي ونظــر ًا النتهــاء وقــت اجللســة مت رفعهــا وتأجيلهــا ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام واملدعــى عليهــم األربعــة املذكوريــن ســابق ًا‬\n‫هــذا وبســؤال املدعــي العــام هــل لديــه بينــة علــى مــا جــاء يف دعــواه مــن أن‬\n‫املدعــى عليــه ‪ .....‬اشــترك مــع املدعــى عليــه األول يف تشــليح الســيارة‬\n‫وقــام بالتســتر عليــه وكذلــك قيــام املدعــى عليــه الرابــع ‪ .....‬بالتســتر‬\n‫ا بينتــي مــا ورد يف أوراق‬     ‫علــى املدعــى عليــه األول ‪ .....‬فأجــاب قائ ـ ً‬\n‫املعاملــة مــن إقــرار املدعــى عليــه ‪ ......‬بذلــك ومــا ورد يف اســتجواب‬\n\n\n                                                                                         ‫‪290‬‬\n\f      ‫املدعــى عليــه ‪ .....‬وأطلــب الرجــوع ألوراق املعاملــة هكــذا أجــاب ثــم‬\n      ‫جــرى منــي االطــاع علــى محضــر اعتــراف املدعــى عليــه ‪ .......‬املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )12‬مــن دفتــر التحقيــق األولــي املرفــق باملعاملــة لفــة‬\n      ‫رقــم (‪ )1‬واملتضمــن مــا نصــه (أقــر أنــا املدعــو‪ ....... /‬ســعودي اجلنســية‬\n      ‫مبوجــب ســجل رقــم (‪ ).....‬وأنــا بكامــل قــواي العقليــة اجلســدية املعتبــرة‬\n      ‫شــرع ًا بأنــي قــد علمــت مــن املدعــو‪ ....... /‬عندمــا كان يأتــي إلــى املنــزل‬\n      ‫بأنــه قــد ســرق ســيارة مــن نــوع ‪ .....‬رقــم اللوحــة (‪ ).....‬وقــام بإيقافهــا أمــام‬\n      ‫املنــزل الــذي أســكن بــه وقــد كلمــت إخوانــي ليكلمــوه ينقلهــا مــن‬\n      ‫أمــام املنــزل ولــم يفعــل ولــم أقــوم بإبــاغ الشــرطة بالســيارة املســروقة‬\n      ‫وقــد علمــت أيضـ ًا بأنــه يقــوم بتفكيــك قطــع منهــا وعلــى ذلــك أوقــع)ا‪.‬‬\n      ‫ه ـ وبعــرض هــذا اإلقــرار علــى املدعــى عليــه ‪ .....‬أجــاب بقولــه هــذا‬\n      ‫اإلقــرار صحيــح ووقعــت عليــه إال أننــي كنــت مكرهــا علــى التوقيــع‬\n      ‫حيــث قامــت الشــرطة بضربــي حتــى وقعــت عليــه هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه ‪ ............‬هــل لديــه بينــة علــى مــا دفــع بــه مــن‬\n      ‫ا ليــس لــدي بينــة هكــذا أجــاب ثــم جــرى‬        ‫دعــوى اإلكــراه فأجــاب قائـ ً‬\n      ‫منــي االطــاع علــى محضــر اســتجواب املدعــى عليــه حيــدر فلــم أجــد‬\n      ‫فيــه مــا يدينــه كمــا جــرى منــي االطــاع علــى باقــي أوراق املعاملــة‬\n      ‫فوجدتهــا مطابقــة ملــا ورد يف دعــوى املدعــي العــام فبنــاء ًا علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث أقــر املدعــى عليــه‬\n      ‫األول ‪ ....‬بســرقة الســيارة الــواردة يف الدعــوى والتصــرف بهــا بتشــليحها‬\n      ‫وهــذا فعــل محــرم ومعاقــب عليــه شــرع ًا وفيــه انتهــاك حلرمــة املســلمني‬\n      ‫األمنــن وأخــذ أموالهــم بغيــر وجــه حــق زاد علــى ذلــك قيامــه بتشــليح‬\n      ‫الســيارة وهــذا الفعــل يوجــب التشــديد يف العقوبــة ومــا دفــع بــه املدعــى‬\n\n\n‫‪291‬‬\n\f‫عليــه ‪ ....‬ال يقبــل منــه وليــس طريق ـ ًا شــرعي ًا بــل فيــه تعــد علــى حقــوق‬\n‫اآلخريــن وترويــع لآلمنــن ومبــا أن املدعــى عليــه الثانــي‪ ....‬أقــر بقيامــه‬\n‫بإيصــال املدعــى عليــه األول مرتــن للســيارة املســروقة وأنــه كان يعلــم‬\n‫أنهــا مســروقة وقبــض عليــه عندهــا وهــذا يف احلقيقــة مشــاركة صريحــة‬\n‫للمدعــى عليــه األول يف ســرقته وتســتر عليــه وفيــه تعــاون علــى اإلثــم‬\n‫والعــدوان ومبــا أن املدعــى عليــه الثالــث ‪ .....‬أقــر بــأن الســيارة كانــت‬\n‫عنــد بيتهــم وأنكــر مشــاركته للســرقة وتســتره علــى املدعــى عليــه‬\n‫األول وأثبــت املدعــي العــام دعــواه باإلقــرار املرصــود آنف ـ ًا وال بينــة‬\n‫للمدعــى عليــه فيمــا دفــع بــه مــن دعــوى اإلكــراه واســتناد ًا حلديــث‬\n‫(البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) ومــا قــام بــه املدعــى‬\n‫عليــه ‪ ....‬يعــد مشــاركة يف الســرقة وتســتر علــى املدعــى عليــه ‪ .....‬وفيــه‬\n‫تعــاون علــى اإلثــم والعــدوان ومبــا أن املــال مــن الضــرورات اخلمــس التــي‬\n‫ورد الشــرع بحفظهــا ومبــا أن املدعــى عليــه الرابــع أنكــر دعــوى املدعــي‬\n‫العــام يف قضيــة التســتر وال بينــة للمدعــي العــام علــى دعــواه واســتناد ًا‬\n‫للحديــث الــوارد أعــاه ومبــا أن احلقــوق العامــة ال يحلــف فيهــا واألصــل‬\n‫بــراءة الذمــة حتــى يثبــت خــاف ذلــك جلميــع مــا ســبق فقــد ثبتــت لــدي‬\n‫دعــوى املدعــي العــام ضــد املدعــى عليهــم الثالثــة ‪ ......‬و ‪ .....‬و ‪.....‬‬\n‫وحكمــت مبــا يلــي أو ًال ‪ :‬تعزيــر املدعــى عليــه األول ‪ ....‬بســجنه مــدة‬\n‫ثــاث ســنوات يحتســب منهــا مــا مت إيقافــه بســبب هــذه القضيــة وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاويات بينهــا عشــرة أيــام‬\n‫ثانيـ ًا ‪ :‬تعزيــر املدعــى عليــه الثاني ‪ .....‬بســجنه مدة ســنة ونصف يحتســب‬\n‫منهــا مــا مت إيقافــه بســبب هــذه القضيــة وجلــده مائــة وخمســن جلــدة‬\n‫مفرقــة علــى ثــاث دفعــات متســاويات بينهــا عشــرة أيــام ثالث ـ ًا ‪ :‬تعزيــر‬\n\n\n                                                                                       ‫‪292‬‬\n\f      ‫املدعــى عليــه الثالــث ‪ .....‬بســجنه مــدة ســبعة أشــهر يحتســب منهــا مــا مت‬\n      ‫إيقافــه بســبب هــذه القضيــة وجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n      ‫متســاويتني بينهمــا عشــرة أيــام رابعـ ًا ‪ :‬رد دعــوى املدعــي العــام يف طلبــه‬\n      ‫تعزيــر املدعــى عليــه الرابــع لعــدم وجــود البينــة املوصلــة وبإعــان احلكــم‬\n      ‫علــى األطــراف قــرر كل واحــد مــن املدعــى عليهــم القناعــة باحلكــم‬\n      ‫أمــا املدعــي العــام فقــرر عــدم القناعــة وطالــب بالتمييــز ورفــع احلكــم‬\n      ‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه لذلــك‬\n      ‫وأمــرت بإخــراج قــرار بذلــك ثــم رفــع احلكــم إلــى محكمــة االســتئناف‬\n                  ‫وصلى اهلل وسلم على نبينا محمد وحرر يف ‪1433/12/22‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/1/25‬ه ـ افتتحــت اجللســة‬\n      ‫يف الســاعة احلاديــة عشــرة هــذا وقــد وردتنــا املعاملــة مــن رئيــس محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب رقــم ‪3418387‬‬\n      ‫وتاريــخ ‪1434/1/19‬ه ـ وقــد ظهــر علــى القــرار مبــا نصــه ( احلمــد هلل‬\n      ‫وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا القــرار رقــم ‪ 33476071‬وتاريــخ‬\n      ‫‪1433/12/22‬ه ـ الصــادر مــن فضيلــة القاضــي الشــيخ ‪ .....‬وأصدرنــا‬\n      ‫القــرار رقــم ‪ 34983‬وتاريــخ ‪1434/1/7‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم قاضــي اســتئناف ‪ ......‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬‬\n      ‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه وللبيــان حــرر يف‬\n          ‫‪1434/1/25‬ه ـ واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":286,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3d7799a5d8efd65dcfff642f1125b80dc557dfd370913bc21a205f9d1424b89c","normalized_text_hash":"fc72b8fb94070eb00a142be4f1c498516f81476b2a43586a85b27821781b0168","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p286-33476071"},{"id":"5faf3026-07b4-57f8-9a94-ab0765f9f670","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة محتويات من منزل اجلار -محاولة إخفاء مسروقات -تسليم مسروقات لصاحبها -محاولة تضليل جهة التحقيق باالدعاء الكاذب -وجود سابقة قضائية «حيازة مخدرات» -التعزير بالسجن واجللد.","document_number":"341243","case_number":"33677954","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/04","year":"1434","subject":"سرقة -سرقة محتويات من منزل اجلار -محاولة إخفاء مسروقات -تسليم مسروقات لصاحبها -محاولة تضليل جهة التحقيق باالدعاء الكاذب -وجود سابقة قضائية «حيازة مخدرات» -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 341243 :‬تاريخه‪1434/01/04 :‬هـ‬\n                     ‫رقم الدعوى‪33677954:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3449726‬تاريخه‪1434/2/27 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة محتويــات مــن منــزل اجلــار‪ -‬محاولــة إخفــاء مســروقات‬\n‫‪ -‬تســليم مســروقات لصاحبهــا ‪ -‬محاولــة تضليــل جهــة التحقيــق‬\n‫باالدعــاء الــكاذب ‪ -‬وجــود ســابقة قضائيــة «حيــازة مخــدرات» ‪ -‬التعزيــر‬\n                                                       ‫بالســجن واجللــد‪.‬‬\n\n\n\n‫‪-1‬قولــه صلــى اهلل عليــه وســلم (واهلل ال يؤمــن كررهــا ثالثـ ًا قالــوا مــن‬\n                                             ‫قــال مــن ال يأمــن جــاره بوائقــه)‪.‬‬\n‫‪-2‬حديــث (لئــن يســرق أحدكــم عشــر مــرات خيــر مــن أن يســرق مــن‬\n                                                             ‫جــاره مــره واحــدة)‪.‬‬\n\n\n\n\n‫دعــوى املدعــى العــام ضــد املدعــى عليــه وطلــب إثبــات إدانتــه بالســرقة‬\n‫مــن منــزل جــاره ومحاولــة تضليــل جهــة التحقيــق بادعــاء تعرضــه لســرقة‬\n‫جهــاز جوالــه ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ بســرقة احــد‬\n‫املنازل وبعد حضور الدوريات األمنية شــوهد املدعى عليه ومت االشــتباه‬\n‫بــه وباســتجوابه اعتــرف بســرقة املنــزل ‪ ،‬أقــر املدعــى عليــه بالدعــوى ‪،‬‬\n‫حكمــت احملكمــة بتعزيــر باملدعــى عليــه بالســجن واجللــد‪ ،‬مت تصديــق‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                      ‫‪294‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا د‪ ....... /‬القاضي يف احملكمة اجلزائية‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ ........‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ ......‬بتاريــخ ‪ ........‬ه ـ ففــي يــوم الســبت املوافــق‪ ......‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪ ......‬قائــا يف دعــواه ‪..........‬‬\n      ‫(‪ 23‬عامـاً) ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).........‬متعلم‬\n      ‫ـ طالــب ـ موقــوف بتاريــخ ‪.......‬ه ـ وأحيــل إلــى ســجن امللــز بأمــر التوقيــف‬\n                                                               ‫رقــم بــدون وتاريــخ ‪........‬هـ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪......‬ه ـ أبلــغ ‪ ..... /‬دوريــات األمــن عــن ســرقة منزلــه ‪،‬‬\n      ‫وبســماع أقوالــه أفــاد بأنــه أثنــاء عودتــه إلــى املنــزل وجــد أحــد الغــرف‬\n      ‫مبعثــرة ومســروق منهــا أســلحة عــدد (‪ )2‬ســاكتون هوائيــة وواحــدة‬\n      ‫ســاكتون ناريــة وثالثــة أطقــم (‪2‬ذهــب) ‪ 1(+‬أملــاس) وســرق مــن الــدور‬\n      ‫األرضــي عــدد ‪ 2‬أجهــزة حاســوب (البتــوب) وال توجــد أي آثار للتكســير‬\n      ‫وأثنــاء البــاغ وتواجــد الفرقــة القابضــة شــوهد املدعــى عليــه واتضــح أنــه‬\n      ‫جــار للمبلــغ واشــتبه بأمــره ومبعاينــة يــده لوحــظ وجــود جــرح يف إبهــام‬\n      ‫اليــد اليمــن وأبلــغ املدعــى عليــه عــن ســرقة جهــاز جوالــه مــن غرفتــه ‪،‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بأنــه قفــز علــى منــزل جــاره (املبلــغ) أثنــاء‬\n      ‫ســفره عــن طريــق ســطح منزلهــم املجــاور ودخــل عــن طريــق بــاب ســطح‬\n      ‫منــزل جــاره حيــث وجــده مفتوحـ ًا ونــزل إلــى الــدور الثانــي وقــام بســرقة‬\n      ‫مجوهــرات وثــاث بنــادق (ســاكتون) ودربيــل وكاميــرا تصويــر فيــدو‬\n      ‫وأجهــزة حاســوب (ال بتــوب) عــدد (‪ )3‬وســاعة يــد وطلقــات شــوزن عــدد‬\n\n‫‪295‬‬\n\f‫(‪100‬طلقــة) وطلقــات خــرازه وجهــازي جــوال وبعــد أن ســرقها أخفاهــا‬\n‫يف منزلــه بإحــدى الغــرف وأقفلهــا‪ ،‬ثــم أحضــر املســروقات وســلمها‬\n                                      ‫لصاحبهــا وصــادق علــى إقــراره شــرعاً‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بالســرقة مــن‬\n‫منــزل جــاره (املبلــغ) املســروقات املنــوه عنهــا ومحاولتــه تضليــل جهــة‬\n                         ‫التحقيــق وبادعــاء تعرضــه لســرقة جهــاز جوالــه‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪1‬ـ اعترافــه املنــوه عنــه املصــادق عليــه شــرع ًا املــدون علــى ص (‪ )1‬مــن‬\n                                              ‫دفتــر التحقيــق املرفــق لفــة (‪.)1‬‬\n‫‪2‬ـ قيامــه بالداللــة علــى املســروقات وإحضارهــا مــن منزلــه وتعــرف املبلــغ‬\n                                                                           ‫عليها‪.‬‬\n                                                ‫‪3‬ـ تطابق أقواله مع بالغ املبلِّغ‪.‬‬\n‫وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة حيــازة مخــدرات‪ .‬وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا وإســاءة‬\n‫حلــق اجلــوار أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫تردعــه وتزجــر غيــره (علمــا بــأن احلــق اخلــاص انتهــى بالتنــازل واســتالم‬\n‫املســروقات)‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪ ...‬اجــاب‬\n‫قائــا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح جملــة وتفصيــا‬\n‫فقــد كان جــاري املالصــق فلــه دبلكــس كان مســافرا فقمــت ودخلــت‬\n‫فلتــه عــن طريــق الســطح حيــث ســطحنا مالصــق لســطح جارنــا وقــد‬\n‫وجــدت بــاب الســطح غيــر مقفــل بقفــل فدخلــت معــه للفلــة وقــد وجــدت‬\n‫مفتــاح ســبير لغرفــة النــوم داخــل الفلــة يف الصالــة فقمــت وفتحــت الغرفــة‬\n‫ووجــدت مجوهــرات وثــاث بنــادق ســاكتون ودربيــل وكاميــرا تصويــر‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫فيديــو واجهــزة حاســوب البتــوب عــدد (‪ )3‬وســاعة يــد وطلقــات شــوزن‬\n      ‫عــدد ( ‪100‬طلقــه ) وطلقــات خــرازة وجهــاز جــوال ووجــدت املجوهــرات‬\n      ‫يف الــدوالب واالســلحة حتــت الســرير فقمــت بســرقتها ووضعهــا يف بيتنــا‬\n      ‫بيــت والــدي وعلــي ســابقة واحــدة حيــازة مخــدرات وانــا موقــوف مــن‬\n      ‫‪1433/8/16‬ه ـ وابلغــت الدوريــات عــن ســرقة جــوال والصحيــح انــه لــم‬\n      ‫يســرق ثــم ابلغتهــم ان جوالــي غيــر مســروق هكــذا اجــاب وقــال املدعــي‬\n      ‫العــام ال اقــول يف جوابــه شــيئا وقــد وجــدت اقوالــه كمــا جــاء يف جوابــه‬\n      ‫ووجــدت اقــراره املصــدق شــرعا كمــا جــاء يف جوابــه وذلــك بدفتــر‬\n      ‫التحقيــق ص (‪ )1‬لفــه (‪ )1‬وقــد جــرى اطالعــي علــى صحيفــة ســوابقه‬\n      ‫فوجــدت لــه ســابقة واحــدة هــي املذكــورة يف الدعــوى ووجــدت انــه‬\n      ‫اوقــف يف ‪.........‬ه ـ فبنــاء جلميــع مــا تقــدم مــن الدعــوى واالجابــة وحيــث‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام واقــر بســرقة منــزل جــاره‬\n      ‫مــن مجوهــرات واســلحة وطلقــات ناريــة وكاميــرا تصويــر فديــو واجهزة‬\n      ‫حاســب وســاعة وجــوال وانــه ابلــغ الدوريــات عــن ســرقة جوالــه وهــو لــم‬\n      ‫يســرق ثــم ابلغهــم انــه لــم يســرق اجلــوال فقــد ثبــت لــدي مــا نســب للمدعــى‬\n      ‫عليــه وحيــث ان فعلــه كبيــرة مــن الكبائــر واذيــة جلــاره وحيــث ان حــق‬\n      ‫اجلــار عظيــم وحيــث أن ســرقته مــن جــاره تســتوجب زيــادة يف عقوبتــه‬\n      ‫لقــول النبــي صلــى اهلل عليــه وســلم ( واهلل ال يؤمــن كررهــا ثالثــا قالــوا‬\n      ‫مــن ؟ قــال مــن ال يأمــن جــاره بوائقــه ) أي أذيتــه وشــروره وفعــل املدعــى‬\n      ‫عليه من االذية والشــرور جلاره ويف احلديث االخر ( لئن يســرق أحدكم‬\n      ‫عشــر مــرات خيــر مــن ان يســرق مــن جــاره مــرة واحــدة) جلميــع مــا تقــدم‬\n      ‫فقــد قــررت مــا يلــي اوال ســجن املدعــى عليــه ‪ ......‬ثــاث ســنوات اعتبــارا‬\n      ‫مــن تاريــخ توقيفــه وجلــده تعزيــرا خمســمائة جلــده مفرقــة علــى دفعــات‬\n\n\n‫‪297‬‬\n\f‫كل دفعــة خمســن جلــده بينهــم مــا ال يقــل عــن اســبوعني ومبــا قــررت‬\n‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام القناعــة‬\n‫ولــم يقنــع املدعــى عليــه وطلــب تدقيــق احلكــم مــن محكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة فأجيــب لطلبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n            ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ ......‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ .......‬وتاريــخ ‪........‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمة الشــيخ‪ /‬د‪ ........ .‬املســجل برقم ‪ .......‬وتاريخ ‪.........‬هـ اخلاص‬\n‫بدعــوى املدعــى العــام ضــد ‪ .......... /‬يف قضيــة ســرقة علــى النحــو‬\n‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة‬\n‫مــا يوجــب املالحظــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":294,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d3b78cc2b710ea3dbe3589a3ad925cf610f3748dd10e1b79539104a1139bf1f","normalized_text_hash":"0ad99fc04d3e5beddf92391648448bbbcf47abc8f9d4cd2990bed3e1db2acf35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p294-341243"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3399f0ff-8ff1-5a72-9337-c2f769321c1a","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -إقرار بالدعوى -ادعاء مرض نفسي -تقرير طبي -عدم وجود سوابق -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"34166318","case_number":"33670030","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/18","year":"1434","subject":"سرقة -سرقة سيارة -إقرار بالدعوى -ادعاء مرض نفسي -تقرير طبي -عدم وجود سوابق -تعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                  ‫رقم الصك ‪ 34166318 :‬تاريخه ‪:‬‬\n            ‫‪1434/03/18‬هـ رقم الدعوى ‪33670030:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34209215‬تاريخه‪1434/5/7 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬إقــرار بالدعــوى ‪ -‬ادعــاء مــرض نفســي ‪ -‬تقريــر‬\n      ‫طبــي ‪ -‬عــدم وجــود ســوابق ‪ -‬تعزيــر بالســجن واجللــد والتوصيــة‬\n                                                           ‫باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                  ‫‪-1‬ما قرره الفقهاء من السرقة من غير حرز فيها التعزير‪.‬‬\n                 ‫‪-2‬ما نصت عليه التعليمات من عدم إطالة سجن األجنبي‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــى العــام ضــد مقيــم بطلــب إثبــات إدانتــه بســرقة ســيارة‬\n      ‫مــن أمــام إحــدى املطاعــم وهــي بوضــع التشــغيل وطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n      ‫بــاغ مفــاده تعــرض ســيارته للســرقة وعثــر عليهــا بقيــادة املدعــى عليــه‬\n      ‫واعتــرف بســرقتها ‪ ،‬أقــر املدعــى عليــه بالدعــوى ودفــع أنــه قام بالســرقة‬\n      ‫مــن غيــر إدراك نظــر ًا ألنــه مريــض نفســي ‪ ،‬متــت مخاطبــة مستشــفى‬\n      ‫الصحــة النفســية للتأكــد مــن حالــة املدعــى عليــه ‪ ،‬ورد اجلــواب مــن إن‬\n      ‫املدعــى عليــه يعانــي مــن اضطــراب القلــق ولكــن ذلــك غيــر مؤثــر علــى‬\n      ‫اإلدراك ‪ ،‬مت احلكــم بإدانــة املدعــى عليــه مبــا نســب إليــه و التعزيــر‬\n      ‫بالســجن واجللــد التوصيــة باإلبعــاد عــن البــاد مت تصديــق احلكــم مــن‬\n\n‫‪261‬‬\n\f                                                          ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 33670030‬وتاريــخ ‪ 1433/11/22‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332086688‬وتاريــخ ‪ 1433/11/22‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1434/03/18‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام ‪.........‬وادعــى بقولــه بصف ــتي مدعيـ ـ ًا عامـ ـ ًا‬\n‫يف دائ ــرة االدع ــاء الع ــام مبدين ــة الري ــاض أدع ــي علــى ‪ 35......... :‬ســنة‬\n‫ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).........‬حيــث أنه بتاريخ‬\n‫‪1433/9/10‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل دوريــات االمــن اثــر‬\n‫بــاغ ملركــز شــرطة ‪ .....‬مــن املواطــن ‪......... /‬يفيــد فيــه بســرقة ســيارته‬\n‫مــن نــوع ‪ .......‬حتمــل لوحــة رقــم (‪ ).........‬مــن امــام احــدى املطاعــم علــى‬\n‫طريــق ‪ ............‬وهــي بوضــع التشــغيل وباســتجوابه اعتــرف بأنــه شــاهد‬\n‫ســيارة متوقفــة بجــوار إحــدى املطاعــم علــى طريــق ‪ ............‬وهــي بوضــع‬\n‫التشــغيل فقــام بســرقتها لغــرض التنقــل عليهــا والهــروب بهــا إلــى حــي‬\n‫‪ ............‬ثــم رجــع الــى حــي ‪ .....‬مــرورا بحــي ‪ .....‬ومت القبــض عليــه وهــو‬\n‫يقــود الســيارة املســروقة وصــادق علــى أقوالــه شــرعا وأســفرت اجــراءات‬\n‫التحقيــق الــى توجيــه االتهــام للمدعــى عليــه بســرقة ســيارة مــن نــوع ‪......‬‬\n‫حتمــل لوحــة رقــم (‪ ).........‬مــن امــام احــد املطاعــم بشــارع ‪ ............‬وهــي‬\n                           ‫بوضــع التشــغيل وذلــك لألدلــة والقرائــن التاليــة ‪- :‬‬\n‫‪ -1‬اعترافــه املصــدق شــرعا بســرقة الســيارة واملــدون علــى صفحــة رقــم‬\n\n                                                                                         ‫‪262‬‬\n\f                                                    ‫(‪ )14‬مــن ملــف التحقيــق رقــم (‪.)1‬‬\n                                ‫‪ -2‬ماتضمنه محضر القبض املرفق لفه رقم (‪.)6‬‬\n                       ‫وبالبحث عن سوابقه لم يعثر له على سوابق حتى تاريخه‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪ -‬هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه بــأن مــا ذكــره املدعــي‬\n      ‫العــام صحيــح جملــة وتفصيــا حيــث قمــت بســرقة الســيارة املذكــورة‬\n      ‫وهــي يف وضــع التشــغيل ألنــي مصــاب بحالــة نفســية وقــد حصــل ذلــك‬\n      ‫وأنــا غيــر مــدرك ملــا حصــل هكــذا أجــاب عليــه فقــد جــرى الكتابــة‬\n      ‫ملجمــع األمــل للصحــة النفســية للكشــف علــى املذكــور واإلفــادة عــن‬\n      ‫حالتــه النفســية مبوجــب خطابنــا رقــم ‪ 3431821‬يف ‪1434/1/6‬ه ـ‬\n      ‫فوردنا تقريرهم رقم ‪ 44/22/1652/371‬يف ‪1434/2/26‬هـ املتضمن‬\n      ‫أنــه مت الكشــف علــى املذكــور وتبــن أنــه يعانــي مــن اضطــراب القلــق‬\n      ‫وليــس ملرضــه تأثيــر علــى إدراكــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وملصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام وألن ســرقة‬\n      ‫الســيارة يف وضــع التشــغيل تعــد ســرقة مــن غيــر حــرز وقــد قــرر الفقهــاء‬\n      ‫أن الســرقة مــن غيــر حــرز فيــه التعزيــر ونظــرا إلــى أن حالتــه النفســية ال‬\n      ‫تؤثــر علــى إدراكــه ونظــرا لعــدم وجــود ســوابق مســجلة عليــه ولكــون‬\n      ‫احلالــة النفســية تقضــي بالتخفيــف عنــه وقــد نصــت التعليمــات علــى عــدم‬\n      ‫إطالــة مــدة ســجن األجنبــي ألن مصيــره الترحيــل لذلــك كلــه فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه بســرقة ســيارة مــن نــوع ‪ .......‬حتمــل لوحــة رقــم‬\n      ‫(‪ ).........‬مــن امــام احــد املطاعــم بشــارع ‪ ............‬وهــي بوضــع التشــغيل‬\n\n\n‫‪263‬‬\n\f‫وحكمــت بتعزيــره بســجنه ملــدة عشــرة أشــهر اعتبــارا مــن تاريــخ إيقافــه‬\n‫وجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات مقــدار كل‬\n‫دفعــة أربعــون جلــدة بــن كل دفعــة واألخــرى مــدة ال تقــل عــن أســبوعني‬\n‫وأوصيــت بترحيلــه إلــى بلــده بعــد انتهــاء محكوميتــه وبعــرض ذلــك علــى‬\n‫الطرفــن قــرر املدعــي العــام عــدم القناعــة وطلــب متييــز احلكــم بــدون‬\n‫الئحــة وقــرر املدعــى عليــه القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪34/522824‬وتاريــخ‪/8‬‬\n‫‪ 1434/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة‬\n‫الشيخ‪........./‬املسجل برقم ‪ 34166318‬وتاريخ ‪1434/ 3 /18‬هـ اخلاص‬\n‫بدعــوى املدعــي العــام ضــد‪ ( ......... /‬ســوداني اجلنســية ) التهامــه بقضيــة‬\n‫ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قــررت الدائــرة باألكثريــة املصادقــة علــى احلكــم و اهلل املوفــق وصلــى‬\n                                 ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪264‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":261,"source_page_end":264,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e148f637519c23e594d8b2498e30dd57ccf82c559df0c951576dcad9f110d8f","normalized_text_hash":"c6da69571d3b623254909122144bb7af089abe648424e7c5d113d45abbe3af9b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p261-34166318"},{"id":"8efb0345-0116-59e3-80a4-e92b5caf079d","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -نشل -تشكيل عصابة -تنوع املضبوطات -التعزير للمدعى عليهما الثالث والرابع بالسجن واجللد لوجود سوابق قضائية -رد دعوى املدعى العام للمدعى عليه األول والثاني .","document_number":"3441904","case_number":"33671081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/19","year":"1434","subject":"سرقة -نشل -تشكيل عصابة -تنوع املضبوطات -التعزير للمدعى عليهما الثالث والرابع بالسجن واجللد لوجود سوابق قضائية -رد دعوى املدعى العام للمدعى عليه األول والثاني .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3441904 :‬تاريخه ‪1434/02/19:‬هـ‬\n                         ‫رقم القضية ‪33671081 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34232554‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬نشــل ‪ -‬تشــكيل عصابــة ‪ -‬تنــوع املضبوطــات ‪ -‬التعزيــر للمدعــى‬\n      ‫عليهمــا الثالــث والرابــع بالســجن واجللــد لوجــود ســوابق قضائيــة ‪ -‬رد‬\n                           ‫دعــوى املدعــى العــام للمدعــى عليــه األول والثانــي ‪.‬‬\n\n\n\n\n                                                     ‫قاعدة ( األصل براءة الذمة ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام علــى أربعــة أشــخاص بتكويــن عصابــة يف النشــل‪،‬‬\n      ‫حيــث مت القبــض علــى املدعــى عليهــم مــن قبــل اجلهــات األمنيــة حيــث‬\n      ‫توفــرت معلومــات عنهــم بتكويــن عصابــة يف النشــل ‪ ،‬وأنهــم مــن أربــاب‬\n      ‫الســوابق ‪ ،‬ويقومــون بالنشــل مــن املعتمريــن يف األماكــن املزدحمــة ‪،‬‬\n      ‫وكانــت حتركاتهــم مريبــة ‪ ،‬فتــم القبــض عليهــم ‪ ،‬ووجــد مــع املدعــى‬\n      ‫عليهــم مبالــغ ماليــة مختلفــة ‪ ،‬وعمــات متنوعــة ‪ ،‬وأجهــزة جوال ‪ ،‬طلب‬\n      ‫تعزيرهــم لقــاء ذلــك وتشــديد العقوبــة علــى املدعــى عليــه الثالــث لكثــرة‬\n      ‫ســوابقه ‪ ،‬واحلكــم بإيــداع مــا مت ضبطــه معهــم يف بيــت املــال ‪ ،‬أنكــر‬\n      ‫املدعــى عليهــم مــا جــاء بدعــوى املدعــى العــام ‪ُ ،‬ط ِلــب مــن املدعــى العــام‬\n      ‫بينتــه علــى دعــواه فقــرر أنــه ليــس لديــه اإل مــا جــاء يف أوراق املعاملــة ‪,‬‬\n      ‫وباالطــاع عليهــا لــم يجــد القاضــي الدليــل القاطــع الدانتهــم ‪ ،‬صــدر‬\n\n‫‪265‬‬\n\f‫احلكــم بــرد دعــوى املدعــى العــام ضــد األول والثانــي ‪ ،‬وتعزيــر املدعــى‬\n‫عليهــم الثالــث والرابــع نظــر ًا لوجــود ســوابق عليهــم يف النشــل ‪ ،‬قنــع‬\n‫املدعــى عليهــم وقــرر املدعــى العــام اعتراضــه علــى احلكــم بالئحــة ‪،‬‬\n                               ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33671081‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332090688‬وتاريــخ‬\n‫‪1433/11/22‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/19‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي العــام املعمــد مــن‬\n‫مرجعــه باخلطــاب رقــم ه ـ م ‪/2 /‬ا‪ 340/‬وتاريــخ ‪1434/1/24‬ه ـ ودعــى‬\n‫علــى احلاضريــن معــه كال مــن ‪ ، ...../1‬البالــغ مــن العمــر (‪ )50‬عام ـ ًا‬\n‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة عــن جــوازات‬\n‫الريــاض برقــم‪ ).....(.....‬و‪ ...../2‬البالــغ مــن العمــر (‪ )54‬عام ـ ًا أفغانــي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة الصــادرة مــن مركــز شــرطة‬\n‫املنصــور برقــم(‪ ).....‬يف ‪1433/9/17‬ه ـ و‪ ، ...../3‬البالــغ مــن العمــر‬\n‫(‪ )54‬عامـ ًا ‪ ،‬أفغانــي اجلنســية ـ مبوجــب البطاقــة البديلــة الصــادرة مــن‬\n‫مركــز شــرطة املنصــور برقــم(‪ ).....‬يف ‪1433/9/17‬ه ـ و‪ ، ...../4‬البالــغ‬\n‫مــن العمــر (‪ )52‬عام ـ ًا ‪ ،‬أفغانــي اجلنســية ـ مبوجــب البطاقــة البديلــة‬\n‫الصــادرة مــن مركــز شــرطة املنصــور برقــم(‪ )......‬يف ‪1433/9/17‬ه ـ‬\n‫قائــا يف دعــواه حيــث انــه بتاريــخ ‪1433/9/17‬ه ـ قبــض علــى املدعــى‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫عليهــم مــن قبــل شــعبة التحريــات والبحــث اجلنائــي بشــرطة العاصمــة‬\n      ‫املقدســة لتوفــر معلومــات عنهــم بتكويــن عصابــة يف النشــل وأنهــم‬\n      ‫مــن إربــاب الســوابق ويتزعمهم(الثانــي) ويقومــون مبمارســة النشــل مــن‬\n      ‫املعتمريــن مــن داخــل احلــرم امللكــي الشــريف واملناطــق املجــاورة لــه‬\n      ‫املزدحمــة باملعتمريــن وتكــون حتركاتهــم أثنــاء محاولــة النشــل علــى‬\n      ‫شــكل مجموعــات لغــرض التغطيــة وامليدانيــة أثنــاء ممارســة عمليــات‬\n      ‫النشــل ومبراقبتهــم أتضــح أنهــم يســكنون يف شــقق (‪ ).....‬بالغرفــة رقــم‬\n      ‫(‪ ).....‬وكانــت حتركاتهــم مريبــة وحذريــن يف حتركاتهــم ويقومــون‬\n      ‫بالتغلغــل بــن املعتمريــن باألماكــن املزدحمــة هــذا وبعــد التأكــد مــن‬\n      ‫تواجــد جميــع أفــراد العصابــة بداخــل ســكنهم مت إعــداد اخلطــة الالزمــة‬\n      ‫يف متــام الســاعة الســابعة صباح ـ ًا املوافــق تاريخــه أعــاه جــرى دخــول‬\n      ‫ســكنهم الكائــن بشــقق ‪ ......‬وبتفتيشــهم عثــر مــع (الثانــي) علــى ألفــن‬\n      ‫وخمســة وثمانــن (‪)2085‬ريــا ًال ســعودي ًا ‪ ،‬ومــع (الثالــث) أربعــة أالف‬\n      ‫ومائتــن وخمســة وعشــرين (‪)4225‬ريــا ًال ســعودي ًا وجهــاز هاتــف نقــال‬\n      ‫نــوع ‪ ...‬وجــواز ســفر باســمه ‪ ،‬ومــع (الرابــع) وجــد بحوزتــه جهــاز مــن نــوع‬\n                                                ‫‪ ...‬بنــي اللــون وجــواز ســفر باســمه ‪.‬‬\n      ‫وبتفتيــش الغرفــة التابعــة للمذكوريــن وجــد حتــت الفرشــة التــي كانــوا‬\n      ‫يجلســون بهــا علــى مبلــغ ألــف وأربعمائــة(‪)1400‬دوالر أمريكــي وألفــن‬\n      ‫وتســعمائة وخمســة وثالثــن (‪ )2935‬ريــا ًال ســعودي ًا وجهــاز ‪ ...‬فضــي‬\n      ‫اللــون وقــد ذكــر جميــع مــن يف الغرفــة عــدم عالقتــه بالنقــود وجهــاز‬\n      ‫الهاتــف النقــال املضبوطــة بالغرفــة (فتــم حجــز جميــع املضبوطــات‬\n                                 ‫بصنــدوق آألمانــات مبركــز شــرطة املنصــور) ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه (األول) أقــر بأنــه ضبــط بحوزتــه جهــاز هاتف‬\n\n\n‫‪267‬‬\n\f‫نقــال واحــد فقــط عائــد إليــه وأمــام مــا يتعلــق بالــدوالرات األمريكيــة‬\n‫ذكــر أنــه شــاهد (الثانــي) يضعهــا أســفل الفرشــة قبــل دخــول رجــال‬\n‫البحــث اجلنائــي عليهــم بوقــت قصيــر ‪ .‬وباســتجواب املدعــى عليــه‬\n‫(الثانــي) أقــر بأنــه ضبــط بحوزتــه مبلــغ قــدرة ثالثــة أالف وثالثمائــة‬\n‫(‪ )3300‬ريــال ســعودي وأن جهــاز الهاتــف النقــال مــن نــوع ‪ ...‬أســود اللــون‬\n‫عائــد إليــه والــذي مت العثــور عليــه حتــت الفرشــة بداخــل الشــقة ‪ ،‬وأنه لم‬\n‫يضــع املبلــغ املالــي املضبــوط حتــت الفرشــة ‪.‬وباســتجواب املدعــى عليــه‬\n‫(الثالــث) أقــر أنــه ضبــط بحوزتــه خمســة أالف (‪ )5000‬ريــال ســعودي‬\n‫وألــف(‪ )1000‬دوالر أمريكــي الــذي وجــد أســفل الفرشــة وجهــاز جــوال‬\n‫أحضرهــا معــه مــن أفغانســتان ‪ .‬وباســتجوابه املدعــى عليــه (الرابــع) أقــر‬\n‫أنــه ضبــط بحوزتــه ألفــا (‪)2000‬ريــال ســعودي و(‪)1900‬ألــف وتســعمائة‬\n‫دوالر أمريكــي وجهــاز هاتــف نقــال وجــدت حتــت الفرشــة وقــد انتهــى‬\n‫التحقيــق إلــى توجيــه االتهــام لهــم بتكويــن عصابــة نشــل وذلــك لألدلــة‬\n                                                             ‫والقرائــن التاليــة‪-:‬‬\n‫‪-1‬مــا ورد مبحضــر القبــض والتفتيــش املنــوه عنه املرفــق على اللفتني(‪)3‬‬\n                                                                             ‫و(‪, )4‬‬\n‫‪-2‬تناقــض أقوالهــم حيــال النقــود وجهــاز الهاتــف النقــال املضبوطــة‬\n‫حتــت الفرشــة بغرفتهــم كمــا يتضــح مــن أقوالهــم املنــوه عنهــا املدونــة‬\n        ‫علــى الصفحــات(‪ )13-2‬بامللفــن املرفقــن علــى اللفــه (‪. )2-1‬‬\n‫‪-3‬تنــوع املضبوطــات واختــاف العمــات دون تقــدمي املدعــى عليهــم‬\n                                                           ‫ملبــرر علــى جمعهــا ‪.‬‬\n‫وبالبحث عن ســوابقهم عثر (للثالث) على خمس(‪ )5‬ســوابق نشــل عودة‬\n‫بعــد إبعــاده باســم‪ .....‬وعثــر (للرابــع) علــى ســابقتني (األولــى‪ :‬لعــب القمار‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫وامليســر والثانيــة‪ :‬نشــل) ولــم يعثــر (لــأول والثانــي) علــى ســوابق مســجلة‬\n      ‫بحقهمــا‪ .‬وحيــث أن مــا قــام بــه املدعــى عليهــم فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n      ‫تعزيريــة والتشــديد علــى (الثالــث) لقــاء تعــدد ســوابقه اســتناد ًا لبرقيــة‬\n      ‫صاحــب الســمو امللكــي نائــب وزيــر الداخليــة رقــم(‪)93958/5/5/1‬‬\n      ‫وتاريــخ ‪1429/8/23‬ه ـ واحلكــم وبإيــداع املضبوطــات بيــت املــال‬\n      ‫اســتناد ًا للمــادة(‪ )92‬مــن نظــام اإلجــراءات اجلزائيــة ‪( .‬علمـ ًا بــأن اليوجــد‬\n      ‫بالقضيــة حــق خــاص) وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــم‬\n      ‫وهــم يتحدثــون العربيــة أنكروهــا كل علــى حــدة جملــة وتفصيــا وقال‬\n      ‫األول والثانــي ال ســوابق لدينــا وقــرر الثالــث قائــا لــدي خمســة ســوابق‬\n      ‫نشــل اخــذت محكوميتهــا وقــرر الرابــع قائــا لــدي ســابقتني نشــل‬\n      ‫وقمــار اخــذت محكوميتهــا جميعــا لــدي وبعــرض ذلــك علــى املدعــي‬\n      ‫العــام قــال الصحيــح ماذكرتــه يف دعــواي وبينتــي ماذكــرت وبالرجــوع‬\n      ‫الــى ادلــة املدعــي العــام وجــدت دليلــه األول محضــر القبــض لفــة‬\n      ‫رقــم ‪ 4/3‬وبالرجــوع اليــه وجتــه يتضمــن (أنــه بتاريــخ ‪1433/9/17‬ه ـ‬\n      ‫قبــض علــى املدعــى عليهــم مــن قبــل شــعبة التحريــات والبحــث اجلنائــي‬\n      ‫بشــرطة العاصمــة املقدســة لتوفــر معلومــات عنهــم بتكويــن عصابــة‬\n      ‫يف النشــل وأنهــم مــن إربــاب الســوابق ويتزعمهم(الثانــي) ويقومــون‬\n      ‫مبمارســة النشــل مــن املعتمريــن مــن داخــل احلــرم امللكــي الشــريف‬\n      ‫واملناطــق املجــاورة لــه املزدحمــة باملعتمريــن وتكــون حتركاتهــم أثنــاء‬\n      ‫محاولــة النشــل علــى شــكل مجموعــات لغــرض التغطيــة وامليدانيــة‬\n      ‫أثنــاء ممارســة عمليــات النشــل ومبراقبتهــم اتضــح أنهــم يســكنون يف‬\n      ‫شــقق ‪ .........‬بالغرفــة رقــم( ) وكانــت حتركاتهــم مريبــة وحذريــن يف‬\n\n\n‫‪269‬‬\n\f‫حتركاتهــم ويقومــون بالتغلغــل بــن املعتمريــن باألماكــن املزدحمــة‬\n‫هــذا وبعــد التأكــد مــن تواجــد جميــع أفــراد العصابــة بداخــل ســكنهم‬\n‫مت إعــداد اخلطــة الالزمــة يف متــام الســاعة الســابعة صباح ـ ًا املوافــق‬\n‫تاريخــه أعــاه جــرى دخــول ســكنهم الكائــن بشــقق منــار التقــوي(‪)1‬‬\n‫وبتفتيشــهم عثــر مــع (الثانــي) علــى ألفــن وخمســة وثمانــن (‪)2085‬‬\n‫ريــا ًال ســعودي ًا ‪ ،‬ومــع (الثالــث) أربعــة أالف ومائتــن وخمســة وعشــرين‬\n‫(‪)4225‬ريــا ًال ســعودي ًا وجهــاز هاتــف نقــال نــوع ‪ ...‬وجــواز ســفر باســمه‬\n‫‪ ،‬ومــع (الرابــع) وجــد بحوزتــه جهــاز مــن نــوع ‪ ...‬بنــي اللــون وجــواز ســفر‬\n‫باســمه‪ .‬وبتفتيــش الغرفــة التابعــة للمذكوريــن وجــد حتــت الفرشــة التــي‬\n‫كانــوا يجلســون بهــا علــى مبلــغ ألــف وأربعمائــة(‪)1400‬دوالر أمريكــي‬\n‫وألفــن وتســعمائة وخمســة وثالثــن (‪ )2935‬ريــا ًال ســعودي ًا وجهــاز ‪...‬‬\n‫فضــي اللــون وقــد ذكــر جميــع مــن يف الغرفــة عــدم عالقتــه بالنقــود‬\n‫وجهــاز الهاتــف النقــال املضبوطــة بالغرفــة (فتم حجــز جميع املضبوطات‬\n‫بصنــدوق آألمانــات مبركــز شــرطة املنصــور) ‪ .‬وبعرضــه علــى املدعــى‬\n‫عليهــم اقــروا بالقبــض وانكــروا الباقــي كمــا رجعــت لدليــل املدعــى‬\n‫عليــه الثانــي وهــو تناقــض اقــوال املدعــى عليهــم حيــال النقــود والهاتــف‬\n‫املضبــوط حتــت الفرشــة بغرفتهــم املــدون ص ‪ 13-2‬لفــة ‪2-1‬وبالرجــوع‬\n‫الــى اســتجوابتهم وجدتهــا كالتالــي (باســتجواب املدعــى عليــه (األول)‬\n‫أقــر بأنــه ضبــط بحوزتــه جهــاز هاتــف نقــال واحــد فقط عائد إليــه وأمام‬\n‫مــا يتعلــق بالــدوالرات األمريكيــة ذكــر أنــه شــاهد (الثانــي) يضعهــا‬\n‫أســفل الفرشــة قبــل دخــول رجــال البحــث اجلنائــي عليهــم بوقــت قصيــر‪.‬‬\n‫وباســتجواب املدعــى عليــه (الثانــي) أقــر بأنــه ضبــط بحوزتــه مبلــغ قــدرة‬\n‫ثالثــة أالف وثالثمائــة (‪ )3300‬ريــال ســعودي وأن جهــاز الهاتــف النقــال‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫مــن نــوع ‪...‬أســود اللــون عائــد إليــه والــذي مت العثــور عليــه حتــت الفرشــة‬\n         ‫بداخــل الشــقة ‪ ،‬وأنــه لــم يضــع املبلــغ املالــي املضبــوط متــت الفرشــة ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه (الثالــث) أقــر أنــه ضبــط بحوزتــه خمســة‬\n      ‫أالف (‪ )5000‬ريــال ســعودي وألــف(‪ )1000‬دوالر أمريكــي الــذي‬\n      ‫وجــد اســفل الفرشــة وجهــاز جــوال أحضرهــا معــه مــن أفغانســتان‪.‬‬\n      ‫وباســتجوابه املدعــى عليــه (الرابــع) أقــر أنــه ضبط بحوزتــه ألفا (‪)2000‬‬\n      ‫ريــال ســعودي و(‪)1900‬ألــف وتســعمائة دوالر أمريكــي الــذي وجهــاز‬\n      ‫هاتــف نقــال وجــدت حتــت الفرشــة ) وبعرضهــا علــى املدعــى عليهــم‬\n      ‫قالــوا ارتبكنــا مــن اخلــوف واعتــرف الرابــع حمايــة اهلل بــان التســعمائة‬\n      ‫دوالر عائــدة لــه وقــرر الثالــث بــأن االلــف دوالر لــه واكتفــى املدعــي‬\n      ‫العــام مباذكــر فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــة وبنــاء علــى‬\n      ‫انــكار املدعــى عليهــم للدعــوى وعــدم قيــام الدليــل القاطــع علــى ادانتهم‬\n      ‫بهــا وألن ماذكــر املدعــي العــام مــن ادلــة توجــه االتهــام للمدعــى عليــه‬\n      ‫الثالــث والرابــع لوجــود ســوابق عليهمــا يف النشــل والترقــى إلدانتهــم‬\n      ‫واألصــل بــراءة الذمــة واعتبــارا لعــدم وجــود ســوابق علــي املدعــى عليهمــا‬\n      ‫األول والثانــي ‪ .....‬و‪ .......‬وألن أقوالهــم بعــد االطــاع عليهــا حتقيقــا لــم‬\n      ‫اجــد فيهــا تناقضــا ظاهــرا بــل وافقــت أقوالهــم قضــاء لــذا كلــه فقــد‬\n      ‫حكمــت مبايلــي‪:‬أوال‪ :‬لــم ثثبــت لــدي ادانــة املدعــى عليهــم مبانســب اليــه‬\n                                      ‫ورددت دعــوى املدعــي العــام املتعلقــة بذلــك‬\n      ‫ثانيــا‪ :‬تتوجــه التهمــة نحــو املدعــى عليهمــا الثالــث والرابــع و وحكمــت‬\n      ‫بتعزيرهمــا لقــاء ذلــك بســجن الثالــث ثمانيــة أشــهر مــن تاريــخ ايقافــه‬\n      ‫وســجن الرابــع ســتة أشــهر مــن تاريــخ ايقافــه وبعرضــه عليهــم قنعــوا بــه‬\n      ‫وقــرر املدعــي العــام االعتــراض بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n‫‪271‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/19‬هـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 3441904‬وتاريــخ‬\n‫‪1434/2/19‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ .....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.....‬‬\n‫املدعــى عليــه باكســتاني اجلنســية ورفقــاه ‪ ،‬املتهمــن يف قضيــة نشــل‪،‬‬\n‫احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":265,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a30d4ccef7a4196c6b41e04b873b1bad334cf2178feb09930e0f9f1597a5ee3","normalized_text_hash":"e81abed8079651cbbdd32bee5a274e22c91947c1b1c3eddc167c976c412de2a2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p265-3441904"},{"id":"41c29c5e-c8b6-5dcb-9c36-3462df34a755","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة بعض محتويات سيارة -مشاركة يف السرقة -رجوع عن اإلقرار -درء حد السرقة -التعزير بالسجن واجللد .","document_number":"3426043","case_number":"33672049","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"سرقة -سرقة بعض محتويات سيارة -مشاركة يف السرقة -رجوع عن اإلقرار -درء حد السرقة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3426043 :‬تاريخه ‪1434/01/28 :‬‬\n                       ‫هـ رقم الدعوى ‪33672049 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34186406‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة بعــض محتويــات ســيارة ‪ -‬مشــاركة يف الســرقة ‪ -‬رجــوع‬\n                 ‫عــن اإلقــرار ‪ -‬درء حــد الســرقة ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                     ‫‪ -‬قوله صلى اهلل عليه وسلم ( احلدود تدرأ بالشبهات ) ‪.‬‬\n      ‫‪ -‬قــال ابــن أبــي عمــر ـ ـ رحمــه اهلل ـ ـ مــن احلنابلــة يف الشــرح الكبيــر‬\n      ‫(‪ ( )208-207/26‬إن شــرط إقامــة احلــد باإلقــرار ‪ -‬البقــاء عليــه إلــى‬\n                              ‫متــام احلــد ‪ -‬فــإن رجــع عــن إقــراره كــف عنــه )‬\n          ‫‪ -‬قال صاحب اإلنصاف عقبه ‪ ( -:‬هذا املذهب يف جميع احلدود ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه باتهامــه بتكســير زجــاج‬\n      ‫ســيارات‪ ،‬وســرقة أربــع مســجالت فيهــا وكاميــرا تلفزيونيــة‪ ،‬تقــدم‬\n      ‫بعــض األشــخاص لإلبــاغ عــن تعــرض زجــاج ســياراتهم للكســر‬\n      ‫وســرقة بعــض احملتويــات منهــا وال يتهمــوا أحــد ًا بالســرقة‪ ،‬وبعــد‬\n      ‫البحــث والتحــري توصلــت اجلهــات األمنيــة أن اللذيــن يقومــان بتكســير‬\n      ‫الســيارات ‪ ،‬همــا كال مــن املدعــى عليــه ‪ ،‬وشــخص آخــر ( فــرزت لــه‬\n      ‫أوراق مستقلة ) ‪ ،‬ومت القبض عليه ‪ ،‬واتضح أنه من أرباب السوابق ‪،‬‬\n      ‫وأقــر بالتهمــة املنســوبة إليــه ‪ ،‬وصــدق اعترافــه شــرعاً‪ ،‬و طلــب املدعــي‬\n‫‪273‬‬\n\f‫العــام إقامــة حــد الســرقة بحقــه كونــه ســرق مــن حــرز محتــرم بالغــا‬\n‫نصابـاً‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام ‪ .‬ـ ـ طلــب مــن‬\n‫املدعــي العــام بينتــه علــى دعــواه ‪ ،‬فذكــر إقــرار املدعــى عليــه املصــدق‬\n‫شــرع ًا و بســؤال املدعــى عليــه عنــه ‪ :‬أعتــرف بصحتــه ‪ ،‬و دفــع بــأن ذلــك‬\n‫كان بإكــراه مــن احملقــق ‪ ،‬و بســؤاله البينــة علــى اإلكــراه ‪ ،‬قرر عدم‬\n‫وجــود بينــة لديــه‪ ،‬ثــم جــرى االطــاع علــى كافــة أوراق املعاملــة و فيهــا‬\n‫احملاضــر املصدقــة مــن البحــث اجلنائــي‪ ،‬حكمــت احملكمــة بصــرف‬\n‫النظــر عــن طلــب املدعــي العــام بإقامــة حــد الســرقة علــى املدعــى عليــه‪،‬‬\n‫واحلكــم بتعزيــر املدعــى عليــه بالســجن و اجللــد نظــر ًا لتوجــه التهمــة‬\n‫القويــة بحقــه‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬و املدعــي العــام لــم يقنــع‬\n‫باحلكــم و طلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة‪ ،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬باالشــتراك مــع صاحــب الفضيلــة‬\n‫الشــيخ ‪ ....‬وصاحــب الفضيلــة الشــيخ ‪ ....‬القضــاة يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ ....‬وتاريــخ ‪ ...‬املقيــدة باحملكمــة برقــم ‪ ....‬وتاريــخ‬\n‫‪ ....‬ففــي يــوم اإلثنــن املوافــق‪ ...‬افتتحــت اجللســة الســاعة ‪ 11 : 30‬وفيهــا‬\n‫قــدم املدعــي العــام ‪ ....‬الئحــة دعــواه ضــد ‪ ....‬ســعودي مبوجــب الســجل‬\n‫ا إنــه بتاريــخ ‪ ....‬تقــدم املواطــن ‪ ، ...‬بشــكوى إلــى‬ ‫املدنــي رقــم ‪ ....‬قائ ـ ً‬\n‫شــرطة ‪ ......‬مفيــد ًا عــن تعــرض زجــاج ســيارته مــن نــوع ‪ .....‬للتكســير‬\n‫وســرق منهــا ام بــي ثــري وكاميــرا مراقبــة تلفزيونيــة ‪،‬وذلــك أثنــاء‬\n\n                                                                                         ‫‪274‬‬\n\f      ‫وقوفهــا أمــام ســكنه بحــي ‪ ....‬وال يتهــم أحــد ًا بعينــه وبتاريــخ ‪ ...‬تقــدم‬\n      ‫املواطــن‪ .../‬بشــكوى لقســم شــرطة ‪ .......‬مفيــد ًا عــن تعــرض زجــاج‬\n      ‫ســيارته مــن نــوع ‪ .....‬للكســر ومحاولــة ســرقة املســجل وال يتهــم أحــد ًا‬\n      ‫وبتاريــخ ‪ ...‬تقــدم املواطــن ‪ ..../‬بشــكوى لقســم الشــرطة مفيــد ًا عــن‬\n      ‫تعــرض زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحــد ًا وبتاريــخ‬\n      ‫‪ ....‬تقــدم املواطــن ‪ .../‬بشــكوى لقســم الشــرطة مفيــد ًا عــن تعــرض‬\n      ‫زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحـ ًـد بذلــك وبــذات‬\n      ‫التاريــخ تقــدم املقيــم‪( ... /‬باكســتاني اجلنسية)لقســم الشــرطة مفيــد ًا‬\n      ‫عــن تعــرض زجــاج ســيارته للكســر وســرقة مســجلها وال يتهــم أحـ ًـد‬\n      ‫بذلــك وبتاريــخ ‪ ....‬تقــدم املواطــن ‪ ...‬لقســم الشــرطة مفيــد ًا عــن تعــرض‬\n      ‫زجــاج ســيارته للكســر وســرقة مســجل الســيارة وال يتهــم أحـ ًـد بذلــك‬\n      ‫وبتاريــخ ‪ ....‬توصلــت أجهــزة البحــث والتحــري بشــرطة ‪ ......‬إلــى أن‬\n      ‫ال مــن املدعــى‬  ‫اللذيــن يقومــان بتكســير زجــاج الســيارات همــا ك ً‬\n      ‫عليــه‪، .....‬واآلخــر ‪( ....‬مت فــرز أوراق مســتقلة لــه مــن قبــل شــرطة‬\n      ‫محافظــة ‪ ......‬وســيتم رفعهــا لســعادة محافــظ ‪ .....‬الحق ـاً) ومت القبــض‬\n      ‫علــى املدعــى عليــه بتاريــخ ‪ ...‬وبالبحــث عــن ســوابقه اتضح أنــه مت ايداعه‬\n      ‫دار املالحظــة االجتماعيــة بتهمــة قيامــه بكســر مرايــا ســيارتني‬\n      ‫وســرقتهما وقــد حكــم عليــه بااللتحــاق بحلقــة حتفيــظ قــرآن ملــدة ســتة‬\n      ‫أشــهر وإذا لــم يلتــزم يســجن شــهر وقــد مت تقديــر تلفيــات ســيارة املواطــن‬\n      ‫‪ ....‬مبلــغ وقــدره (‪2000‬ريــال)‪ .‬وتلفيــات ســيارة املواطــن‪ ... /‬فتقــدر مببلــغ‬\n      ‫(‪ )510‬أمــا ســيارة املواطــن‪ ... /‬فتــم تقديــر تلفيــات ســيارته مببلــغ وقــدره‬\n      ‫(‪410‬ريــال) أمــا تلفيــات ســيارة املقيــم‪ ... /‬فتقــدر مبلــغ وقــدره‬\n      ‫(‪1430‬ريال)وقــد مت االتصــال علــى املواطــن ‪ ...‬إلحظــار تقديــر تلفيــات‬\n\n\n‫‪275‬‬\n\f‫ســيارته ولكنــه لــم يحضــر حتــى تاريخــه ‪،‬أمــا مايخــص تقديــر تلفيــات‬\n‫املواطــن ‪ ...‬فقــد تنــازل عــن حقــه اخلــاص وباســتجواب املدعــى عليــه أقــر‬\n‫أنــه قبــل يومــن مــن تاريــخ القبــض عليــه كان بشــارع ‪ ...‬مبحافظــة ‪......‬‬\n‫وحضــر لــه شــخص يدعــى ‪ ....‬وطلــب منــه مســجل ســيارة ثــم ركــب معــه‬\n‫واجتهــا إلــى حــي ‪ ......‬بحث ـ ًا عــن ســيارة فلــم يجــدا ثــم خرجــا مــن احلــي‬\n‫وشــاهدا ســيارة مــن نــوع ‪ .....‬فتوقفــا عندهــا وقــام ‪ ...‬بأخــذ ســكروب‬\n‫وكســر الزجــاج اخللفــي للســيارة مــن جهــة اليمــن ثــم قــام بفــك املســجل‬\n‫وأعطــاه للمدعــو ‪ ...‬مقابــل (‪150‬ريال)‪،‬وأقــر كذلــك أنــه ســبق وأن قــام‬\n‫بكســر زجــاج ســيارة مــن نــوع ‪ ......‬كانــت متوقفــة بالقــرب مــن مركــز‬\n‫‪ .....‬محــاوال الســرقة منهــا لكنــه لــم يجــد شــيئ ًا ولــم يكــن معــه أحــد ًا ‪،‬‬\n‫كمــا أقــر بكســر الزجــاج اخللفــي مــن جهــة اليســار لســيارة مــن نــوع ‪.....‬‬\n‫وقــام بســرقة املســجل وبيعــه علــى أحــد األشــخاص مببلــغ (‪150‬ريــال)‬\n‫ولــم يشــاركه أحــد ‪ ،‬كمــا أقــر بكســر زجــاج ســيارة مــن نــوع ‪ .....‬ولــم‬\n‫يجــد فيهــا شــيئ ًا ‪ ،‬وأقــر كذلــك بأنــه قــام بكســر زجــاج ســيارة مــن‬\n‫نــوع ‪ ......‬وســرق منهــا مشــغل صوتيــات(‪ )MP3‬ولــم يشــاركه أحــد ًا وال‬\n‫يــزال اجلهــاز يف املنــزل ‪ ،‬كمــا أقــر بكســر زجــاج ســيارة مــن نــوع ‪.....‬‬\n‫بهــدف الســرقة لكنــه لــم يجــد فيهــا شــيئ ًا ‪ ،‬وبانتقــال املختصــن يف‬\n‫جهــة الضبــط ومعاينــة الســيارات التــي مت ذكرهــا بالشــكوى تبــن‬\n‫لهــم تعــرض تلــك الســيارات لكســر زجاجهــا والســرقة منهــا وبضبــط‬\n‫شــهادة املواطــن ‪ ..../‬أفــاد بــأن قــام بشــراء مســجل ســيارة مــن املدعــى‬\n‫عليــه مببلــغ (‪150‬ريــال) وال يعلــم بأنــه مســروق وقــد انتهــى التحقيــق مــع‬\n‫املدعــى عليــه ‪ ....‬إلــى اتهامــه بتكســير زجــاج (‪ )6‬ســت ســيارات وســرقة‬\n‫أربــع مســجالت منهــا وجهــاز صوتيــات (‪،)MP3‬وكاميــرا تلفزيونيــة‬\n\n\n                                                                                         ‫‪276‬‬\n\f      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 -:‬مــا جــاء يف إقــراره املصــدق شــرع ًا‬\n      ‫املــدون علــى الصفحــة رقــم (‪)6‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ -2 .)3‬ماجــاء يف إفــادة املواطــن ‪ .....‬املــدون علــى الصفحــة رقــم (‪)14‬‬\n      ‫مــن ملــف االســتدالل املرفــق لفــه رقــم (‪ -3)1‬مــا جاء يف محضــر االنتقال‬\n      ‫واملعاينــة املــدون علــى الصفحــة رقــم (‪)4‬مــن ملــف االســتدالل املرفــق لفــه‬\n      ‫رقــم (‪ ،)2‬و محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)10‬‬\n      ‫مــن ملــف االســتدالل املرفــق لفــه رقــم (‪ ،)7‬ومحضــر االنتقــال واملعاينــة‬\n      ‫املــدون علــى الصفحــة رقــم (‪)2‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ ،)8‬ومحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)2‬مــن‬\n      ‫ملــف االســتدالل املرفــق لفــه رقــم (‪ ،)6‬ومحضــر االنتقــال واملعاينــة‬\n      ‫املــدون علــى الصفحــة رقــم (‪)2‬مــن ملــف االســتدالل املرفــق لفــه رقــم‬\n      ‫(‪ ،)5‬ومحضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪)2‬مــن‬\n      ‫ملــف االســتدالل املرفــق لفــه رقــم (‪-4)4‬ماجــاء باحملضــر املعــد مــن قبــل‬\n      ‫التحريــات والبحــث اجلنائــي املرفــق لفــه رقــم (‪-5.)41‬ماجــاء يف تقديــر‬\n      ‫التلفيــات املرفــق لفــه رقــم (‪)61-60-59-58-57-56-55-54‬وحيــث‬\n      ‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم مــن حــرزه‬\n      ‫بعــد هتكــه يزيــد عــن النصــاب الشــبهة لــه فيــه ولكــون اجلانــي مكلف‬\n      ‫وغيــر مكــره أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة (علمــا‬\n      ‫بــأن احلــق اخلــاص اليــزال قائم ـ ًا فيمــا يخــص املدعــي ‪ ...‬واملدعــي ‪...‬‬\n      ‫واملدعــي ‪ ، ...‬وانتهــى بالتنــازل فيمــا يخــص املدعــي ‪ ...‬واملقيــم ‪)...‬‬\n      ‫ا‬ ‫وبســؤال املدعــى عليــه عمــا جــاء يف الئحــة املدعــي العــام أجــاب قائ ـ ً‬\n\n\n‫‪277‬‬\n\f‫كل مــا جــاء يف الئحــة املدعــي العــام غيــر صحيــح فلــم أقــم بتكســير‬\n‫زجــاج ســت ســيارات وســرقة أربــع مســجالت منهــا وجهــاز صوتيــات‬\n‫(‪ )MP3‬وكاميــرا تلفزيونيــة وال شــيئ ًا مــن ذلــك هكــذا أجــاب فجــرى‬\n‫ا بينتــي مــايف أوراق املعاملــة‬ ‫ســؤال املدعــي العــام عــن بينتــه فأجــاب قائـ ً‬\n‫فجــرى االطــاع علــى أوراق املعاملــة ومنهــا اإلقــرار املصــدق شــرع ًا‬\n‫واملــدون علــى لفــة (‪ )3‬صفحــة (‪ )6‬وهــذا نــص احلاجــة منــه ( أقــر أنــا‬\n‫احلــدث ‪ ...‬أننــي قمــت بتكســير زجــاج عــدة ســيارات وذلــك مبحافظــة‬\n‫‪ ......‬وهــي ‪ .......‬رقــم اللوحــة‪ ... ...‬كانــت متوقفــة بحــارة األحــوال املدنيــة‬\n‫وذلــك قبــل ثــاث أيــام حيــث قمــت بكســر زجاجهــا اخللفــي األميــن‬\n‫بواســطة طابوقــة وقمــت بفــك املســجل بواســطة ســكروب وقمــت ببيعــه‬\n‫علــى املدعــو ‪ ...‬مببلــغ (‪ )150‬ريــال أيض ـ ًا وقمــت بكســر زجاجــة ‪......‬‬\n‫حيــث كانــت متوقفــة بشــارع عشــرين حيــث قمــت بكســر زجاجهــا‬\n‫األمامــي األيســر وقمــت بتفتيشــها ولــم أحصــل شــيء وقمــت بكســر‬\n‫زجــاج ســيارة مــن نــوع ‪ .......‬حيــث قمــت بكســر الزجــاج اخللفــي األيســر‬\n‫ولــم أعثــر علــى شــيء بداخلهــا وقمــت بكســر زجــاج ســيارة مــن نــوع ‪......‬‬\n‫حيــث قمــت بكســر زجاجهــا األميــن ولــم أعثــر علــى شــيء بداخلهــا‬\n‫وقمــت بكســر زجــاج ‪ ......‬حيــث قمــت بكســر زجاجهــا األميــن وذلــك‬\n‫قبــل خمســة عشــر يومـ ًا ولــم أعثــر علــى شــيء هــذا إقــراري وعليــه جــرى‬\n‫ا صحيــح أننــي‬     ‫التوقيــع) فجــرت مجابهتــه بهــذا اإلقــرار فأجــاب قائ ـ ً‬\n‫قلــت ذلــك ولكــن احملقــق قــال لــي اعتــرف وأخرجــك اآلن وأكرهنــي‬\n‫علــى هــذا اإلقــرار فســألناه هــل لديــك بينــة فأجــاب قائــا ليــس لــدي‬\n‫بينــة كمــا جــرى االطــاع علــى إفــادة املواطــن ‪ ...‬لفــة(‪ )1‬صفحــة (‪)14‬‬\n‫وهــذا نــص احلاجــة منهــا ( أقــر أنــا املواطــن ‪ ....‬بأننــي اشــتريت مــن املدعــو‬\n\n\n                                                                                          ‫‪278‬‬\n\f      ‫‪ ....‬قبــل شــهر تقريب ـ ًا مســجل تويوتــا مببلــغ قــدره ألــف وخمســمئة ريــال‬\n      ‫حيــث وجدتــه بشــارع عشــرين علــى قدميــه وكان لوحــده وعرضــه علــي‬\n      ‫واشــتريته منــه وال أعلــم هــل هــو مســروق أو ال) فجــرى ســؤال املدعــى‬\n      ‫ا هــذا الــكالم غيــر صحيــح كمــا جــرى‬           ‫عليــه عــن ذلــك فأجــاب قائ ـ ً‬\n      ‫االطــاع علــى محاضــر االتصــال واملعاينــة لفــه (‪ 2‬ـ ‪ 4‬ـ ‪ 5‬ـ ‪ 6‬ـ ‪ 7‬ـ ‪ )8‬كمــا‬\n      ‫جــرى االطــاع علــى احملضــر املعــد مــن قبــل التحريــات والبحــث اجلنائــي‬\n      ‫لفــة (‪ )41‬واملتضمــن ( أفيدكــم أنــا آمــر دوريــات البحــث اجلنائــي وبعــد‬\n      ‫التحــري عــن األشــخاص الذيــن يقومــون بكســر زجــاج الســيارات‬\n      ‫وســرقة املســجالت وتفتيشــها وســرقة مــا بهــا مــن محتويــات وبعــد‬\n      ‫التحــري والبحــث الدقيــق عــن األشــخاص اتضــح لــي ووردتنــا معلومــات‬\n      ‫ال مــن املدعــو ‪...‬‬\n                        ‫مــن مصــادري اخلاصــة أن الذيــن يقومــون بالســرقة ك ً‬\n      ‫واملدعــو‪ ....‬هــذا للعلــم واإلحاطــة ) وبســؤال املدعــى عليــه عــن جميــع‬\n      ‫ا ‪ :‬ال صحــة لذلــك والصحيــح مــا ذكــرت ثــم ســألنا‬            ‫ذلــك أجــاب قائ ـ ً‬\n      ‫ا ال ســوابق علــي وهلل احلمــد ثــم‬‫املدعــى عليــه عــن ســوابقه فأجــاب قائـ ً‬\n      ‫جــرى ســؤال األطــراف هــل لديهــم مــا يضيفــون فأجــاب كل واحــد‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫منهمــا بأنــه ال إضافــة لديــه فبنـ ً‬\n      ‫وبعــد االطــاع علــى طيــات املعاملــة وإلنــكار املدعــى عليــه مانســب إليــه‬\n      ‫ا وبالنظــر إلــى إقــرار املدعــى عليــه املصــدق شــرع ًا‬         ‫جملــة وتفصي ـ ً‬\n      ‫واملذكــور أعــاه وإلــى إفــادة املواطــن ‪ ....‬وكذلــك إلــى محاضــر‬\n      ‫االنتقــال واملعاينــة ومحضــر التحريــات والبحــث اجلنائــي املذكــور أعــاه‬\n      ‫ولرجــوع املدعــى عليــه عــن إقــراره وادعائــه اإلكــراه ولكــون الرجــوع‬\n      ‫عــن اإلقــرار مقبــول قــال صاحــب الشــرح ( إن شــرط إقامــة احلــد باإلقرار‬\n      ‫البقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) ‪207/26‬‬\n\n\n‫‪279‬‬\n\f‫ـ ‪ 208‬قــال صاحــب اإلنصــاف ( هــذا املذهــب يف جميــع احلــدود ) وألن‬\n‫ادعــاء اإلكــراه شــبهة يــدرأ بهــا احلــد وقــد روي عــن النبــي صلــى اهلل‬\n‫عليــه وســلم أنــه قــال ( احلــدود تــدرأ بالشــبهات ) وبعــد تأكــد مــن خلــو‬\n‫صحيفــة املدعــى عليــه مــن الســوابق كمــا هــو مــدون يف طيــات املعاملــة‬\n‫وحلداثــة ســنه وجلميــع مــا تقــدم فلــم يثبــت لدينــا إدانــة ‪ ....‬بتكســير زجــاج‬\n‫(‪ )6‬ســت ســيارات وســرقة أربــع مســجالت منهــا وجهــاز صوتيــات‬\n‫(‪ )MP3‬وكاميــرا تلفزيونيــة وقررنــا صــرف النظــر عــن طلــب املدعــي‬\n‫العــام إقامــة حــد الســرقة علــى املدعــى عليــه ولكــن لتوجــه التهمــة‬\n‫القويــة عليــه فقــد قررنــا تعزيــره مبــا يلــي‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ملــدة‬\n‫ســنتني ونصــف مــع احتســاب املــدة التــي أمضاهــا يف التوقيــف ثاني ـاً‪:‬‬\n‫جلــد املدعــى عليــه مائتــان وخمســون جلــدة مفرقــة علــى خمــس دفعــات‬\n‫بــن كل دفعــة والتــي تليهــا مــاال يقــل عــن عشــرة أيــام وبذلــك حكمنــا‬\n‫وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة باحلكــم وقــرر املدعــي‬\n‫العــام املعارضــة مــع تقــدمي الئحــة وأفهــم مبقتضــى تعليمــات االســتئناف‬\n‫وأن عليــه تقــدمي الئحــة اعتراضيــة خــال مــدة أقصاهــا ثالثــون يومـ ًا مــن‬\n‫تاريــخ اســتالمه نســخة مــن احلكــم وإذا لــم يقــدم الئحتــه خــال هــذه‬\n‫املــدة فســترفع املعاملــة إلــى محكمــة االســتئناف كاملتبــع وقــد جــرى‬\n‫تســليم املدعــي العــام نســخة مــن احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n    ‫على نبينا محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪1434/01/26‬هـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم ‪ ...‬وتاريــخ‬\n‫‪1434/3/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n\n\n                                                                                            ‫‪280‬‬\n\f      ‫القضــاة الشــيخ ‪ ...‬والشــيخ ‪ ...‬و‪ ....‬برقــم ‪ ....‬وتاريــخ ‪1434/1/28‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ....‬يف قضيــة ســرقة وقــد تضمــن‬\n      ‫القــرار حكــم أصحــاب الفضيلــة علــى النحــو املفصــل فيــه وبدارســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــرر باالكثريــة املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم‪.‬‬\n\n\n\n\n‫‪281‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":273,"source_page_end":281,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f3a288ae60c71c2e61311c9444fa182d65f1e1f6f351d130b0fed0da05ba067","normalized_text_hash":"ba9362846027bba31b990262765fc996bd1ea7c7af4c62cf546a06287026a9e4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p273-3426043"},{"id":"bd69d2d5-4ae3-5e80-b0f9-454c16883941","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -قيادة سيارة مسروقة -وجود سوابق قضائية - طلب تشديد عقوبة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن","document_number":"33475432","case_number":"33672219","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/1","year":"1434","subject":"سرقة -سرقة سيارة -قيادة سيارة مسروقة -وجود سوابق قضائية - طلب تشديد عقوبة -إقرار بالدعوى -ثبوت إدانة -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33475432 :‬تاريخه‪1433/12/1 :‬هـ‬\n                     ‫رقم الدعوى‪33672219:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 348557‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬قيادة ســيارة مســروقة ‪ -‬وجود ســوابق قضائية ‪-‬‬\n‫طلــب تشــديد عقوبــة ‪ -‬إقــرار بالدعــوى ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n                                                                     ‫واجللد‪.‬‬\n\n\n\n\n                                   ‫القاعدة الفقهية (املرء مؤاخذ بإقراره)‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى املقدمــة مــن املدعــي العــام ضــد شــخص مــن أربــاب‬\n‫الســوابق بســرقة ســيارة متوقفــة أمــام منــزل صاحبهــا وســرقتها‪ ،‬طلــب‬\n‫املدعــي العــام إثبــات مــا ُأســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫وتشــديد العقوبــة لتعــدد ســوابقه‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n‫بــاغ مــن أحــد املواطنــن مفــاده تعــرض ســيارته للســرقة فتــم القبــض‬\n‫علــى املدعــى عليــه وهــو يقــود الســيارة ‪ ،‬أقــر املدعــى عليــه بالدعــوى‬\n‫ومصادقتــه علــى الســوابق‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه‬\n‫بالســجن واجللــد‪ ،‬تشــديد التعزيــر بحقــه‪ ،‬مت تصديــق احلكــم مــن‬\n                                                     ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n                                                                                  ‫‪282‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 33672219‬وتاريــخ ‪1433/11/23‬ه ـ‬           ‫ّ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332087425‬وتاريــخ ‪ 1433/11/22‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافق‪1433/12/21‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 30‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .......‬و ادعــى علــى احلاضــر معــه ‪ .....‬ســعودي‬\n      ‫اجلنســية ســجل املدنــي رقــم (‪ )........‬أنــه يف متــام الســاعة التاســعة وخمــس‬\n      ‫وثالثــن دقيقــة مســاء يــوم االربعــاء املوافــق ‪1433/10/4‬ه ـ تبلــغ مركــز‬\n      ‫شــرطة املنتــزه مــن املواطــن ‪ ........‬عــن تعــرض ســيارته من نــوع‪ ........‬لوحة‬\n      ‫رقــم (‪ ) .....‬للســرقة مــن أمــام منزلــه وال يتهــم احــد بســرقتها ومت اتخــاذ‬\n      ‫جملــة مــن اإلجــراءات البحثيــة والتعميــم عــن الســيارة املســروقة وبتاريــخ‬\n      ‫‪1433/10/9‬ه ـ أبلــغ املواطــن ‪.......‬عــن تلقيــه اتصــال مــن الشــرطة أنــه‬\n      ‫مت القبــض علــى ســيارته بقيــادة املدعــى عليــه ومت مكاتبــة مديــر‬\n      ‫الشــرطة لبعــث املركبــة والقائــد إلــى مركــز شــرطة ‪ ....‬ومت اســتالم‬\n      ‫املذكــور واملركبــة مــن شــرطة ‪ .....‬وبســماع أقــوال املدعــى عليــه أقــر‬\n      ‫أنــه قــام بأخــذ الســيارة نــوع‪ ......‬مــن أمــام أحــد املنــازل بحــي ‪ ......‬وال‬\n      ‫يعــرف صاحبهــا وأنــه مت القبــض عليــه مــن قبــل شــرطة ‪ ....‬والســيارة‬\n      ‫بقيادتــه وبالبحــث يف ســجله اجلنائــي عثــر لــه علــى ســبع ســوابق وهــي‪:‬‬\n      ‫‪)1‬قيــادة الســيارة وهــو بحالــة ســكر ‪ +‬شــرب املســكر ‪ +‬حيــازة ســاح‬\n      ‫دون ترخيــص ‪ +‬حيــازة الذخيــرة ‪ +‬مخالفــة التعليمــات ‪ ) 2‬ســرقة ســيارة‬\n      ‫‪)3‬ســرقة ســيارة ‪ ) 4‬التلفــظ بألفــاظ غيــر الئقــة ‪ ) 5‬مضاربــة ‪ ) 6‬شــرب‬\n\n‫‪283‬‬\n\f‫مســكرات وســرقة ســيارة ‪ ) 7‬حريــق وقــد أســفر التحقيــق معــه عــن‬\n‫اتهامــه بســرقة الســيارة مــن نــوع ‪ ......‬لوحــة رقــم (‪ )...........‬عندمــا كانت‬\n‫متوقفــة أمــام منــزل صاحبهــا بحــي ‪ ......‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬مــا جــاء باعترافــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪،14، 13‬‬\n‫‪ )15‬املرفــق باللفــة رقــم ( ‪ - 2 .)3‬القبــض عليــه مــن قبــل شــرطة ‪....‬‬\n‫وبقيادتــه الســيارة املســروقة املشــار لــه واملــدون علــى الصفحــة رقــم (‪)20‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره وتشــديد العقوبــة‬\n‫عليــه لتعــدد ســوابقه التــي لــم تردعــه عقوباتهــا الســابقة علم ـ ًا أن احلــق‬\n‫اخلــاص انتهــى بالتنــازل وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح جمل ـ ًة‬        ‫أجــاب قائ ـ ً‬\n‫ا وقــد قمــت بســرقه ســيارة نــوع ‪ .....‬مــن أحــد املنــازل بحــي ‪......‬‬ ‫وتفصيـ ً‬\n‫وجدتهــا مفتحــه االبــواب وذهبــت بهــا إلــى مكــة وتهــت يف الطريــق ومت‬\n‫القبــض علــي يف ‪......‬هكــذا أجــاب وبعــد االطــاع علــى أوراق املعاملــة‬\n‫وجــدت للمدعــى عليــه ســبع ســوابق منهــا ثــاث ســوابق ســرقه وبعــرض‬\n‫ذلــك علــى املدعــى عليــه قــال الســوابق صحيحــه فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى و اإلجابــة ومبــا أن املدعــى عليــه أقــر مبــا جــاء يف دعــوى‬\n‫املدعــي العــام ومبــا ان املــرء مؤاخــذ بإقــراره ومبــا أن فعلــه هــذا فعــل‬\n‫محــرم ملــا فيــه مــن إيــذاء لألخريــن و اعتــداء علــى أموالهــم وترويعهــم‬\n‫ومبــا أن املدعــى عليــه ســوابق لــم تردعــه عقوباتهــا عــن فعلتــه هــذه لــذا‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بســرقة ســيارة مــن نــوع ‪ ......‬عندمــا‬\n‫كانــت متوقفــة أمــام منــزل صاحبهــا بحــي ‪ ،......‬حكمــت عليــه تعزيــر ًا‬\n\n\n                                                                                        ‫‪284‬‬\n\f                                                                                ‫مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬ســجن املدعــى عليــه ملــدة ســنتني ويحســب لــه كل ســجن بــه يف‬\n      ‫هــذه القضيــة ثانيـاً‪ :‬جلــد املدعــى عليــه ثالثمائــة جلــده مفرقــة علــى ســت‬\n      ‫دفعــات بــن كل دفعــة وأخــرى خمســة عشــر يومـ ًا وبعــرض احلكــم على‬\n      ‫املدعــى عليــه و املدعــي العــام قــررا كل منهمــا عــدم القناعــة وطلبــا‬\n      ‫رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــه و اهلل املوفــق‬\n                ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/12/21‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n      ‫املختصــة بتدقيــق القضايــا اجلزائية مبحكمة االســتئناف مبنطقة حائل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبنطقــة‬\n      ‫حائــل برقــم ‪ 332087425‬يف تاريــخ ‪1434 / 1 / 6 :‬ه ـ واملقيــدة لدينــا‬\n      ‫برقم ‪ 3455854‬يف تاريخ ‪1434 / 1 / 7 :‬هـ املرفق بها القرار الشرعي‬\n      ‫الصــادر مــن صاحــب الفضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة اجلزائية‬\n      ‫مبنطقــة حائــل برقــم ‪ 33475432‬يف تاريــخ‪1433/12/21 :‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد‪ ........ :‬ســعودي بالســجل املدنــي رقــم‪)........( :‬‬\n      ‫بشــأن ســرقه ســيارة وقــد تضمــن القــرار حكــم صاحــب الفضيلــة وفقــه‬\n      ‫اهلل علــى املدعــى عليــه علــى النحــو املفصــل يف القــرار املرفــق ‪ ،‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى ماحكــم‬\n      ‫بــه فضيلتــه بالقــرار املشــار إليــه مــع تنبيــه فضيلتــه ينبغــي وضع شــاهدين‬\n      ‫علــى بصمــه املدعــى عليــه مســتقبال حســب التعليمــات املرعيــة واهلل‬\n                      ‫املوفــق وصلــى وســلم علــى نبينــا محمــد والــه وصحبــه وســلم‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":282,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"87129049b897cf597185605856269565b0e16e07d42461b6181d572928a6d71d","normalized_text_hash":"49cfc3f89645a6c232e236fcdb85a747a9bb61c98c51a655fb2b94cd82065b7a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p282-33475432"},{"id":"072e2627-ed96-5f32-94fd-f363f7f031b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة وتشليحها -اشتراك يف سرقة -تصرف يف مسروق -تستر -تشديد عقوبة -رجوع عن إقرار -طلب بينة على انتزاع اكراه -ثبوت إدانة -رد دعوى لعدم وجود بينة موصلة - تعزير بالسجن واجللد .","document_number":"33476071","case_number":"33675694","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"سرقة -سرقة سيارة وتشليحها -اشتراك يف سرقة -تصرف يف مسروق -تستر -تشديد عقوبة -رجوع عن إقرار -طلب بينة على انتزاع اكراه -ثبوت إدانة -رد دعوى لعدم وجود بينة موصلة - تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33476071 :‬تاريخه‪1433/12/22 :‬هـ‬\n                       ‫رقم الدعوى‪33675694:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34983‬تاريخه‪1434/1/7 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة وتشــليحها ‪ -‬اشــتراك يف ســرقة ‪ -‬تصــرف يف‬\n‫مســروق ‪ -‬تســتر ‪ -‬تشــديد عقوبــة ‪ -‬رجــوع عــن إقــرار ‪ -‬طلــب بينــة علــى‬\n‫انتــزاع اكــراه ‪ -‬ثبــوت إدانــة ‪ -‬رد دعــوى لعــدم وجــود بينــة موصلــة ‪-‬‬\n                                                  ‫تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                ‫‪ -‬حديث البينة على املدعي واليمني على املدعى عليه‪.‬‬\n                ‫‪ -‬املال من الضرورات اخلمس التي ورد الشرع بحفظها‪.‬‬\n\n\n\n\n‫دعــوى املدعــى العــام ضــد أربعــة أشــخاص بطلــب إثبــات إدانــة األول‬\n‫بســرقة ســيارة والتصــرف بهــا بتشــليحها واشــتراك الثانــي والثالــث‬\n‫يف تشــليح الســيارة وتســترهما مــع الرابــع علــى األول‪ ،‬وطلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليهــم واحلكــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى‬\n‫املدعــى عليهــم بعــد بالغــن بســرقة ســيارتني وبعــد البحــث والتحــري‬\n‫قبــض علــى املدعــى عليهــم ومت التحقيــق معهــم وباســتجوابهم اعترفــوا‬\n‫مبــا نســب إليهــم ‪ ،‬أقــر املدعــى عليــه األول بالدعــوى ‪ ،‬كما أقر املدعى‬\n‫عليــه الثانــي ‪ ،‬أنكــر املدعــى عليــه الثالــث ‪ ،‬وجــد إقــرار حتقيقــا علــى‬\n‫املدعــى عليــه الثالــث‪ ،‬أنكــر املدعــى عليــه الرابــع ‪ ،‬وعــدم وجــود بينــة‬\n                                                                                     ‫‪286‬‬\n\f      ‫علــى املدعــى عليــه الرابــع ‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليهــم‬\n      ‫األول والثانــي والثالــث بالســجن واجللــد ‪ ،‬ورد دعــوى املدعــى العــام ضــد‬\n         ‫املدعــى عليــه الرابــع‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1433/12/21‬ه ـ لــدي أنــا ‪......‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف افتتحــت اجللســة يف‬\n      ‫الســاعة التاســعة صباحـ ًا بنــاء ًا علــى املعاملــة احملالــة لنــا مــن رئيــس هــذه‬\n      ‫احملكمــة برقــم ‪ 33675694‬يف ‪1433/11/24‬ه ـ واملقيــدة لــدى‬\n      ‫احملكمــة بالقيــد رقــم ‪ 332113017‬يف ‪1433/11/24‬ه ـ ويف هــذه‬\n      ‫ا بصفتــي مدعيـ ًا عامــا يف‬    ‫اجللســة حضــر املدعــي العــام ‪ .......‬وقــرر قائـ ً‬\n      ‫دائــرة التحقيــق واالدعــاء العام مبحافظة القطيــف أدعي على‪،.......-1 :‬‬\n      ‫البالــغ مــن العمــر (‪)21‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ ).....‬غيــر محصــن ‪ ،‬متســبب ‪ ،‬املقبــوض عليــه بتاريــخ‬\n      ‫‪1433/10/1‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف اســتنادا للقــرار‬\n      ‫الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ ، ......-2‬البالــغ مــن العمــر‬\n      ‫(‪)21‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر‬\n      ‫محصــن ‪ ،‬متســبب ‪ ،‬املقبــوض عليــه بتاريــخ ‪1433/10/1‬ه ـ ‪ ،‬وأحيــل‬\n      ‫لســجن محافظــة القطيــف اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬هـ ‪ ، .......-3‬البالغ من العمر (‪)23‬عام ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر محصــن ‪ ،‬عاطــل ‪ ،‬املقبــوض‬\n      ‫عليــه بتاريــخ ‪1433/10/1‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة القطيــف‬\n      ‫اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪،......-4‬‬\n‫‪287‬‬\n\f‫البالــغ مــن العمــر (‪)32‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )......‬محصــن ‪ ،‬موظــف أهلــي ‪ ،‬املقبــوض عليــه بتاريــخ‬\n‫‪1433/10/1‬ه ـ ‪ ،‬مفــرج عنــه اســتناد ًا للمــادة (‪ )120‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم مبحافظــة ‪ ....‬حيــث أنــه بتاريــخ‬\n‫‪1433/9/24‬ه ـ ورد بــاغ ملركــز شــرطة ‪ .....‬مــن قبــل‪ ...... /‬عــن تعــرض‬\n‫ســيارته مــن نــوع ‪ ....‬رقــم اللوحــة (‪ ).....‬للســرقة مــن املوقــع الــذي تركهــا‬\n‫بــه ‪ ....‬علــى شــارع ‪ ....‬بجــوار البنــك ‪ ............‬وبتاريــخ ‪1433/10/1‬ه ـ ورد‬\n‫بــاغ ملركــز شــرطة ‪ ....‬مــن قبــل‪ ..... /‬مخبــر ًا عــن وجــود ســيارة مــن نــوع‬\n‫‪ ....‬مشــلحة مبزرعتــه الواقعــة ‪ .....‬وبانتقــال محقــق القضيــة إلــى موقــع‬\n‫الســيارة املذكــورة اتضــح أن عبــارة عــن مزرعــة بالقــرب مــن كوبــري‬\n‫املطــار وبالوصــول إليــه شــوهدت الســيارة املذكــورة مشــلحة بالكامــل‬\n‫وليــس بهــا كفــرات وباســتجواب املدعــى عليــه األول (‪ )....‬أقــر بقيامــه‬\n‫بســرقة وتشــليح وإخفــاء ســيارة املبلــغ ‪ .....‬مــن نــوع ‪ ......‬وأخبــر بذلــك‬\n‫الثانــي والثالــث وكان الثانــي هــو من يقوم بإيصاله إلى ‪ ....‬وباســتجواب‬\n‫املدعــى عليــه الثانــي (‪ )......‬أقــر بأنــه كان يعلــم بالســرقة وكان يعــاون‬\n‫املدعــى عليــه األول يف تشــليح الســيارة املذكــورة وباســتجواب املدعــى‬\n‫عليــه الثالــث (‪ )....‬أقــر بعلمــه بســرقة املدعــى عليــه األول للســيارة ويعلــم‬\n‫أن أنــه يقــوم بتفكيــك الســيارة املذكــورة وباســتجواب املدعــى عليــه‬\n‫الرابــع (‪ ).....‬أقــر بعلمــه بوجــود الســيارة املســروقة مــن قبــل األول أمــام‬\n‫منزلهــم وقــد انتهــى التحقيــق معهــم إلــى توجيــه االتهــام إليهــم بســرقة‬\n‫األول ســيارة مــن نــوع (‪ ).......‬والتصــرف بهــا بتشــليحها وباشــتراك الثاني‬\n‫والثالــث لــه يف تشــليح الســيارة وتســترهما مــع الرابــع علــى األول وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬إقــرار املدعــى عليــه األول املــدون علــى‬\n\n\n                                                                                        ‫‪288‬‬\n\f      ‫الصفحــة رقــم (‪ )10‬مــن اللفــة رقــم (‪ -2 )1‬إقــرار املدعــى عليــه الثانــي‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )11‬مــن لفــة رقــم (‪ -3 )1‬إقــرار املدعــى‬\n      ‫عليــه الثالــث املــدون علــى الصفحــة رقــم (‪ )12‬مــن لفــة رقــم (‪)1‬‬\n      ‫‪-4‬محضــر االنتقــال واملعاينــة املعــد مــن قبــل فرقــة البحــث اجلنائــي‬\n      ‫بشــرطة مركــز ‪ ......‬رقــم (بــدون) تاريــخ ‪1433/10/1‬ه ـ املنــوه عنــه‬\n      ‫علــى الصفحــة رقــم (‪ )2‬لفــة (‪ -5 )2‬مــا جــاء يف أقــوال املدعــى عليــه‬\n      ‫الرابــع املدونــة علــى الصفحــات رقــم (‪ )12،11،10‬مــن ملــف التحقيــق‬\n      ‫لفــة رقــم (‪ )2‬وبالبحــث عــن ســوابقهم لــم يعثــر لهــم علــى ســوابق جنائيــة‬\n      ‫علــى املســتوى العــام وحيــث إن مــا أقــدم عليــه املذكــورون ‪ -‬وهــم‬\n      ‫بكامــل أهليتهــم املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n      ‫تعزيريــة تزجرهــم وتــردع غيرهــم (علم ـ ًا بــأن احلــق اخلــاص قــد انتهــى‬\n      ‫بالتنــازل) هــذه دعــواي وبــاهلل التوفيــق هــذا كمــا حضــر يف اجللســة ‪.....‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ .....‬وبســؤاله عــن دعــوى املدعــي‬\n      ‫العــام أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬\n      ‫فقــد قمــت بســرقة ســيارة ‪ ......‬مــن نــوع ‪ .....‬مــن بيــت صاحبــه بعــد نزولــه‬\n      ‫منهــا وتصرفــت بهــا بتشــليحها لوحــدي وكان ســبب ذلــك أنني اشــتريت‬\n      ‫مــن املدعــو ‪ .....‬ســيارة أخــرى غيــر هــذه الســيارة واســتلمتها منــه ثــم‬\n      ‫أخذهــا منــي بالغفلــة مــن عنــد بيتــي فغضبــت مــن تصرفــه فقمــت بســرقة‬\n      ‫ســيارته هــذا جوابــي هــذا وقــد حضــر يف اجللســة ‪ ....‬ســعودي مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .........‬وبســؤاله عــن دعــوى املدعــي العــام أجــاب‬\n      ‫بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن أننــي اشــتركت مــع‬\n      ‫املدعــى عليــه األول يف ســرقة الســيارة ‪ .....‬غيــر صحيــح بــل الصحيــح هــو‬\n\n\n‫‪289‬‬\n\f‫أننــي أقــوم بتوصيــل املدعــى عليــه األول ‪ ....‬للســيارة املذكــورة ‪ .....‬حيــث‬\n‫أنــه ال يوجــد لديــه ســيارة وقمــت بتوصيلــه مرتــن وقــد علمــت بــأن‬\n‫الســيارة مســروقة قبــل القبــض علينــا بيومــن ولــم أخبــر عــن ذلــك ألننــي‬\n‫مشــغول وقبــض علينــا عنــد الســيارة املســروقة عنــد بيــت ‪ .....‬هــذا جوابي‬\n‫هــذا كمــا حضــر يف اجللســة ‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n‫‪ ......‬وبســؤاله عــن دعــوى املدعــي العــام أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام يف دعــواه غيــر صحيــح بــل الصحيــح هــو أن املدعــى عليــه ‪ .....‬يقــوم‬\n‫بإصــاح ســيارات عنــد منزلنــا ‪ .....‬وأخبــرت إخوانــي بــأن يكلمــوه‬\n‫وكان مــن ضمــن الســيارات هــذه الســيارة املســروقة إال أننــي لــم أكــن‬\n‫أعلــم أنهــا مســروقة إال بعــد حضــور األدلــة اجلنائيــة هــذا جوابــي هــذا‬\n‫كمــا حضــر يف اجللســة ‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫وبســؤاله عــن دعــوى املدعــي العــام أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n‫يف دعــواه مــن أننــي متســتر علــى املدعــى عليــه األول غيــر صحيــح بــل‬\n‫الصحيــح هــو أننــي كنــت جالــس يف الديوانيــة وســمعتهم يقولــون‬\n‫الســيارة التــي عنــد املنــزل تعــود للمدعــى عليــه ‪ .....‬ولــم أكــن أعلــم أنهــا‬\n‫مســروقة ولــم أشــاهدها ولــم أشــاهد املدعــى عليــه يقــوم بتشــليحها هــذا‬\n‫جوابــي ونظــر ًا النتهــاء وقــت اجللســة مت رفعهــا وتأجيلهــا ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام واملدعــى عليهــم األربعــة املذكوريــن ســابق ًا‬\n‫هــذا وبســؤال املدعــي العــام هــل لديــه بينــة علــى مــا جــاء يف دعــواه مــن أن‬\n‫املدعــى عليــه ‪ .....‬اشــترك مــع املدعــى عليــه األول يف تشــليح الســيارة‬\n‫وقــام بالتســتر عليــه وكذلــك قيــام املدعــى عليــه الرابــع ‪ .....‬بالتســتر‬\n‫ا بينتــي مــا ورد يف أوراق‬     ‫علــى املدعــى عليــه األول ‪ .....‬فأجــاب قائ ـ ً‬\n‫املعاملــة مــن إقــرار املدعــى عليــه ‪ ......‬بذلــك ومــا ورد يف اســتجواب‬\n\n\n                                                                                         ‫‪290‬‬\n\f      ‫املدعــى عليــه ‪ .....‬وأطلــب الرجــوع ألوراق املعاملــة هكــذا أجــاب ثــم‬\n      ‫جــرى منــي االطــاع علــى محضــر اعتــراف املدعــى عليــه ‪ .......‬املــدون‬\n      ‫علــى الصفحــة رقــم (‪ )12‬مــن دفتــر التحقيــق األولــي املرفــق باملعاملــة لفــة‬\n      ‫رقــم (‪ )1‬واملتضمــن مــا نصــه (أقــر أنــا املدعــو‪ ....... /‬ســعودي اجلنســية‬\n      ‫مبوجــب ســجل رقــم (‪ ).....‬وأنــا بكامــل قــواي العقليــة اجلســدية املعتبــرة‬\n      ‫شــرع ًا بأنــي قــد علمــت مــن املدعــو‪ ....... /‬عندمــا كان يأتــي إلــى املنــزل‬\n      ‫بأنــه قــد ســرق ســيارة مــن نــوع ‪ .....‬رقــم اللوحــة (‪ ).....‬وقــام بإيقافهــا أمــام‬\n      ‫املنــزل الــذي أســكن بــه وقــد كلمــت إخوانــي ليكلمــوه ينقلهــا مــن‬\n      ‫أمــام املنــزل ولــم يفعــل ولــم أقــوم بإبــاغ الشــرطة بالســيارة املســروقة‬\n      ‫وقــد علمــت أيضـ ًا بأنــه يقــوم بتفكيــك قطــع منهــا وعلــى ذلــك أوقــع)ا‪.‬‬\n      ‫ه ـ وبعــرض هــذا اإلقــرار علــى املدعــى عليــه ‪ .....‬أجــاب بقولــه هــذا‬\n      ‫اإلقــرار صحيــح ووقعــت عليــه إال أننــي كنــت مكرهــا علــى التوقيــع‬\n      ‫حيــث قامــت الشــرطة بضربــي حتــى وقعــت عليــه هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه ‪ ............‬هــل لديــه بينــة علــى مــا دفــع بــه مــن‬\n      ‫ا ليــس لــدي بينــة هكــذا أجــاب ثــم جــرى‬        ‫دعــوى اإلكــراه فأجــاب قائـ ً‬\n      ‫منــي االطــاع علــى محضــر اســتجواب املدعــى عليــه حيــدر فلــم أجــد‬\n      ‫فيــه مــا يدينــه كمــا جــرى منــي االطــاع علــى باقــي أوراق املعاملــة‬\n      ‫فوجدتهــا مطابقــة ملــا ورد يف دعــوى املدعــي العــام فبنــاء ًا علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث أقــر املدعــى عليــه‬\n      ‫األول ‪ ....‬بســرقة الســيارة الــواردة يف الدعــوى والتصــرف بهــا بتشــليحها‬\n      ‫وهــذا فعــل محــرم ومعاقــب عليــه شــرع ًا وفيــه انتهــاك حلرمــة املســلمني‬\n      ‫األمنــن وأخــذ أموالهــم بغيــر وجــه حــق زاد علــى ذلــك قيامــه بتشــليح‬\n      ‫الســيارة وهــذا الفعــل يوجــب التشــديد يف العقوبــة ومــا دفــع بــه املدعــى‬\n\n\n‫‪291‬‬\n\f‫عليــه ‪ ....‬ال يقبــل منــه وليــس طريق ـ ًا شــرعي ًا بــل فيــه تعــد علــى حقــوق‬\n‫اآلخريــن وترويــع لآلمنــن ومبــا أن املدعــى عليــه الثانــي‪ ....‬أقــر بقيامــه‬\n‫بإيصــال املدعــى عليــه األول مرتــن للســيارة املســروقة وأنــه كان يعلــم‬\n‫أنهــا مســروقة وقبــض عليــه عندهــا وهــذا يف احلقيقــة مشــاركة صريحــة‬\n‫للمدعــى عليــه األول يف ســرقته وتســتر عليــه وفيــه تعــاون علــى اإلثــم‬\n‫والعــدوان ومبــا أن املدعــى عليــه الثالــث ‪ .....‬أقــر بــأن الســيارة كانــت‬\n‫عنــد بيتهــم وأنكــر مشــاركته للســرقة وتســتره علــى املدعــى عليــه‬\n‫األول وأثبــت املدعــي العــام دعــواه باإلقــرار املرصــود آنف ـ ًا وال بينــة‬\n‫للمدعــى عليــه فيمــا دفــع بــه مــن دعــوى اإلكــراه واســتناد ًا حلديــث‬\n‫(البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) ومــا قــام بــه املدعــى‬\n‫عليــه ‪ ....‬يعــد مشــاركة يف الســرقة وتســتر علــى املدعــى عليــه ‪ .....‬وفيــه‬\n‫تعــاون علــى اإلثــم والعــدوان ومبــا أن املــال مــن الضــرورات اخلمــس التــي‬\n‫ورد الشــرع بحفظهــا ومبــا أن املدعــى عليــه الرابــع أنكــر دعــوى املدعــي‬\n‫العــام يف قضيــة التســتر وال بينــة للمدعــي العــام علــى دعــواه واســتناد ًا‬\n‫للحديــث الــوارد أعــاه ومبــا أن احلقــوق العامــة ال يحلــف فيهــا واألصــل‬\n‫بــراءة الذمــة حتــى يثبــت خــاف ذلــك جلميــع مــا ســبق فقــد ثبتــت لــدي‬\n‫دعــوى املدعــي العــام ضــد املدعــى عليهــم الثالثــة ‪ ......‬و ‪ .....‬و ‪.....‬‬\n‫وحكمــت مبــا يلــي أو ًال ‪ :‬تعزيــر املدعــى عليــه األول ‪ ....‬بســجنه مــدة‬\n‫ثــاث ســنوات يحتســب منهــا مــا مت إيقافــه بســبب هــذه القضيــة وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات متســاويات بينهــا عشــرة أيــام‬\n‫ثانيـ ًا ‪ :‬تعزيــر املدعــى عليــه الثاني ‪ .....‬بســجنه مدة ســنة ونصف يحتســب‬\n‫منهــا مــا مت إيقافــه بســبب هــذه القضيــة وجلــده مائــة وخمســن جلــدة‬\n‫مفرقــة علــى ثــاث دفعــات متســاويات بينهــا عشــرة أيــام ثالث ـ ًا ‪ :‬تعزيــر‬\n\n\n                                                                                       ‫‪292‬‬\n\f      ‫املدعــى عليــه الثالــث ‪ .....‬بســجنه مــدة ســبعة أشــهر يحتســب منهــا مــا مت‬\n      ‫إيقافــه بســبب هــذه القضيــة وجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n      ‫متســاويتني بينهمــا عشــرة أيــام رابعـ ًا ‪ :‬رد دعــوى املدعــي العــام يف طلبــه‬\n      ‫تعزيــر املدعــى عليــه الرابــع لعــدم وجــود البينــة املوصلــة وبإعــان احلكــم‬\n      ‫علــى األطــراف قــرر كل واحــد مــن املدعــى عليهــم القناعــة باحلكــم‬\n      ‫أمــا املدعــي العــام فقــرر عــدم القناعــة وطالــب بالتمييــز ورفــع احلكــم‬\n      ‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه لذلــك‬\n      ‫وأمــرت بإخــراج قــرار بذلــك ثــم رفــع احلكــم إلــى محكمــة االســتئناف‬\n                  ‫وصلى اهلل وسلم على نبينا محمد وحرر يف ‪1433/12/22‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/1/25‬ه ـ افتتحــت اجللســة‬\n      ‫يف الســاعة احلاديــة عشــرة هــذا وقــد وردتنــا املعاملــة مــن رئيــس محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب رقــم ‪3418387‬‬\n      ‫وتاريــخ ‪1434/1/19‬ه ـ وقــد ظهــر علــى القــرار مبــا نصــه ( احلمــد هلل‬\n      ‫وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا القــرار رقــم ‪ 33476071‬وتاريــخ‬\n      ‫‪1433/12/22‬ه ـ الصــادر مــن فضيلــة القاضــي الشــيخ ‪ .....‬وأصدرنــا‬\n      ‫القــرار رقــم ‪ 34983‬وتاريــخ ‪1434/1/7‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم قاضــي اســتئناف ‪ ......‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬‬\n      ‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ .....‬ختمــه وتوقيعــه وللبيــان حــرر يف‬\n          ‫‪1434/1/25‬ه ـ واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪293‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":286,"source_page_end":293,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3d7799a5d8efd65dcfff642f1125b80dc557dfd370913bc21a205f9d1424b89c","normalized_text_hash":"fc72b8fb94070eb00a142be4f1c498516f81476b2a43586a85b27821781b0168","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p286-33476071"},{"id":"5faf3026-07b4-57f8-9a94-ab0765f9f670","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة محتويات من منزل اجلار -محاولة إخفاء مسروقات -تسليم مسروقات لصاحبها -محاولة تضليل جهة التحقيق باالدعاء الكاذب -وجود سابقة قضائية «حيازة مخدرات» -التعزير بالسجن واجللد.","document_number":"341243","case_number":"33677954","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/04","year":"1434","subject":"سرقة -سرقة محتويات من منزل اجلار -محاولة إخفاء مسروقات -تسليم مسروقات لصاحبها -محاولة تضليل جهة التحقيق باالدعاء الكاذب -وجود سابقة قضائية «حيازة مخدرات» -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 341243 :‬تاريخه‪1434/01/04 :‬هـ‬\n                     ‫رقم الدعوى‪33677954:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3449726‬تاريخه‪1434/2/27 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة محتويــات مــن منــزل اجلــار‪ -‬محاولــة إخفــاء مســروقات‬\n‫‪ -‬تســليم مســروقات لصاحبهــا ‪ -‬محاولــة تضليــل جهــة التحقيــق‬\n‫باالدعــاء الــكاذب ‪ -‬وجــود ســابقة قضائيــة «حيــازة مخــدرات» ‪ -‬التعزيــر‬\n                                                       ‫بالســجن واجللــد‪.‬‬\n\n\n\n‫‪-1‬قولــه صلــى اهلل عليــه وســلم (واهلل ال يؤمــن كررهــا ثالثـ ًا قالــوا مــن‬\n                                             ‫قــال مــن ال يأمــن جــاره بوائقــه)‪.‬‬\n‫‪-2‬حديــث (لئــن يســرق أحدكــم عشــر مــرات خيــر مــن أن يســرق مــن‬\n                                                             ‫جــاره مــره واحــدة)‪.‬‬\n\n\n\n\n‫دعــوى املدعــى العــام ضــد املدعــى عليــه وطلــب إثبــات إدانتــه بالســرقة‬\n‫مــن منــزل جــاره ومحاولــة تضليــل جهــة التحقيــق بادعــاء تعرضــه لســرقة‬\n‫جهــاز جوالــه ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد بــاغ بســرقة احــد‬\n‫املنازل وبعد حضور الدوريات األمنية شــوهد املدعى عليه ومت االشــتباه‬\n‫بــه وباســتجوابه اعتــرف بســرقة املنــزل ‪ ،‬أقــر املدعــى عليــه بالدعــوى ‪،‬‬\n‫حكمــت احملكمــة بتعزيــر باملدعــى عليــه بالســجن واجللــد‪ ،‬مت تصديــق‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                      ‫‪294‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا د‪ ....... /‬القاضي يف احملكمة اجلزائية‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ ........‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ ......‬بتاريــخ ‪ ........‬ه ـ ففــي يــوم الســبت املوافــق‪ ......‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪ ......‬قائــا يف دعــواه ‪..........‬‬\n      ‫(‪ 23‬عامـاً) ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).........‬متعلم‬\n      ‫ـ طالــب ـ موقــوف بتاريــخ ‪.......‬ه ـ وأحيــل إلــى ســجن امللــز بأمــر التوقيــف‬\n                                                               ‫رقــم بــدون وتاريــخ ‪........‬هـ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪......‬ه ـ أبلــغ ‪ ..... /‬دوريــات األمــن عــن ســرقة منزلــه ‪،‬‬\n      ‫وبســماع أقوالــه أفــاد بأنــه أثنــاء عودتــه إلــى املنــزل وجــد أحــد الغــرف‬\n      ‫مبعثــرة ومســروق منهــا أســلحة عــدد (‪ )2‬ســاكتون هوائيــة وواحــدة‬\n      ‫ســاكتون ناريــة وثالثــة أطقــم (‪2‬ذهــب) ‪ 1(+‬أملــاس) وســرق مــن الــدور‬\n      ‫األرضــي عــدد ‪ 2‬أجهــزة حاســوب (البتــوب) وال توجــد أي آثار للتكســير‬\n      ‫وأثنــاء البــاغ وتواجــد الفرقــة القابضــة شــوهد املدعــى عليــه واتضــح أنــه‬\n      ‫جــار للمبلــغ واشــتبه بأمــره ومبعاينــة يــده لوحــظ وجــود جــرح يف إبهــام‬\n      ‫اليــد اليمــن وأبلــغ املدعــى عليــه عــن ســرقة جهــاز جوالــه مــن غرفتــه ‪،‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بأنــه قفــز علــى منــزل جــاره (املبلــغ) أثنــاء‬\n      ‫ســفره عــن طريــق ســطح منزلهــم املجــاور ودخــل عــن طريــق بــاب ســطح‬\n      ‫منــزل جــاره حيــث وجــده مفتوحـ ًا ونــزل إلــى الــدور الثانــي وقــام بســرقة‬\n      ‫مجوهــرات وثــاث بنــادق (ســاكتون) ودربيــل وكاميــرا تصويــر فيــدو‬\n      ‫وأجهــزة حاســوب (ال بتــوب) عــدد (‪ )3‬وســاعة يــد وطلقــات شــوزن عــدد‬\n\n‫‪295‬‬\n\f‫(‪100‬طلقــة) وطلقــات خــرازه وجهــازي جــوال وبعــد أن ســرقها أخفاهــا‬\n‫يف منزلــه بإحــدى الغــرف وأقفلهــا‪ ،‬ثــم أحضــر املســروقات وســلمها‬\n                                      ‫لصاحبهــا وصــادق علــى إقــراره شــرعاً‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بالســرقة مــن‬\n‫منــزل جــاره (املبلــغ) املســروقات املنــوه عنهــا ومحاولتــه تضليــل جهــة‬\n                         ‫التحقيــق وبادعــاء تعرضــه لســرقة جهــاز جوالــه‪.‬‬\n                                                ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪1‬ـ اعترافــه املنــوه عنــه املصــادق عليــه شــرع ًا املــدون علــى ص (‪ )1‬مــن‬\n                                              ‫دفتــر التحقيــق املرفــق لفــة (‪.)1‬‬\n‫‪2‬ـ قيامــه بالداللــة علــى املســروقات وإحضارهــا مــن منزلــه وتعــرف املبلــغ‬\n                                                                           ‫عليها‪.‬‬\n                                                ‫‪3‬ـ تطابق أقواله مع بالغ املبلِّغ‪.‬‬\n‫وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة حيــازة مخــدرات‪ .‬وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا وإســاءة‬\n‫حلــق اجلــوار أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫تردعــه وتزجــر غيــره (علمــا بــأن احلــق اخلــاص انتهــى بالتنــازل واســتالم‬\n‫املســروقات)‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه ‪ ...‬اجــاب‬\n‫قائــا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح جملــة وتفصيــا‬\n‫فقــد كان جــاري املالصــق فلــه دبلكــس كان مســافرا فقمــت ودخلــت‬\n‫فلتــه عــن طريــق الســطح حيــث ســطحنا مالصــق لســطح جارنــا وقــد‬\n‫وجــدت بــاب الســطح غيــر مقفــل بقفــل فدخلــت معــه للفلــة وقــد وجــدت‬\n‫مفتــاح ســبير لغرفــة النــوم داخــل الفلــة يف الصالــة فقمــت وفتحــت الغرفــة‬\n‫ووجــدت مجوهــرات وثــاث بنــادق ســاكتون ودربيــل وكاميــرا تصويــر‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫فيديــو واجهــزة حاســوب البتــوب عــدد (‪ )3‬وســاعة يــد وطلقــات شــوزن‬\n      ‫عــدد ( ‪100‬طلقــه ) وطلقــات خــرازة وجهــاز جــوال ووجــدت املجوهــرات‬\n      ‫يف الــدوالب واالســلحة حتــت الســرير فقمــت بســرقتها ووضعهــا يف بيتنــا‬\n      ‫بيــت والــدي وعلــي ســابقة واحــدة حيــازة مخــدرات وانــا موقــوف مــن‬\n      ‫‪1433/8/16‬ه ـ وابلغــت الدوريــات عــن ســرقة جــوال والصحيــح انــه لــم‬\n      ‫يســرق ثــم ابلغتهــم ان جوالــي غيــر مســروق هكــذا اجــاب وقــال املدعــي‬\n      ‫العــام ال اقــول يف جوابــه شــيئا وقــد وجــدت اقوالــه كمــا جــاء يف جوابــه‬\n      ‫ووجــدت اقــراره املصــدق شــرعا كمــا جــاء يف جوابــه وذلــك بدفتــر‬\n      ‫التحقيــق ص (‪ )1‬لفــه (‪ )1‬وقــد جــرى اطالعــي علــى صحيفــة ســوابقه‬\n      ‫فوجــدت لــه ســابقة واحــدة هــي املذكــورة يف الدعــوى ووجــدت انــه‬\n      ‫اوقــف يف ‪.........‬ه ـ فبنــاء جلميــع مــا تقــدم مــن الدعــوى واالجابــة وحيــث‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام واقــر بســرقة منــزل جــاره‬\n      ‫مــن مجوهــرات واســلحة وطلقــات ناريــة وكاميــرا تصويــر فديــو واجهزة‬\n      ‫حاســب وســاعة وجــوال وانــه ابلــغ الدوريــات عــن ســرقة جوالــه وهــو لــم‬\n      ‫يســرق ثــم ابلغهــم انــه لــم يســرق اجلــوال فقــد ثبــت لــدي مــا نســب للمدعــى‬\n      ‫عليــه وحيــث ان فعلــه كبيــرة مــن الكبائــر واذيــة جلــاره وحيــث ان حــق‬\n      ‫اجلــار عظيــم وحيــث أن ســرقته مــن جــاره تســتوجب زيــادة يف عقوبتــه‬\n      ‫لقــول النبــي صلــى اهلل عليــه وســلم ( واهلل ال يؤمــن كررهــا ثالثــا قالــوا‬\n      ‫مــن ؟ قــال مــن ال يأمــن جــاره بوائقــه ) أي أذيتــه وشــروره وفعــل املدعــى‬\n      ‫عليه من االذية والشــرور جلاره ويف احلديث االخر ( لئن يســرق أحدكم‬\n      ‫عشــر مــرات خيــر مــن ان يســرق مــن جــاره مــرة واحــدة) جلميــع مــا تقــدم‬\n      ‫فقــد قــررت مــا يلــي اوال ســجن املدعــى عليــه ‪ ......‬ثــاث ســنوات اعتبــارا‬\n      ‫مــن تاريــخ توقيفــه وجلــده تعزيــرا خمســمائة جلــده مفرقــة علــى دفعــات‬\n\n\n‫‪297‬‬\n\f‫كل دفعــة خمســن جلــده بينهــم مــا ال يقــل عــن اســبوعني ومبــا قــررت‬\n‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام القناعــة‬\n‫ولــم يقنــع املدعــى عليــه وطلــب تدقيــق احلكــم مــن محكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة فأجيــب لطلبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n            ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ ......‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ .......‬وتاريــخ ‪........‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمة الشــيخ‪ /‬د‪ ........ .‬املســجل برقم ‪ .......‬وتاريخ ‪.........‬هـ اخلاص‬\n‫بدعــوى املدعــى العــام ضــد ‪ .......... /‬يف قضيــة ســرقة علــى النحــو‬\n‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة‬\n‫مــا يوجــب املالحظــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":294,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0d3b78cc2b710ea3dbe3589a3ad925cf610f3748dd10e1b79539104a1139bf1f","normalized_text_hash":"0ad99fc04d3e5beddf92391648448bbbcf47abc8f9d4cd2990bed3e1db2acf35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p294-341243"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
